{
  "name": "aetheria",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Aetheria — a small Genshin-inspired open-world prototype for the browser.",
  "scripts": {
    "dev": "vite --port 3002 --host 0.0.0.0",
    "build": "vite build --base ./",
    "preview": "vite preview --port 3002 --host 0.0.0.0"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^7.1.0"
  }
}

@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');

:root {
  --ink: #06131e;
  --ink-2: #0b2032;
  --panel: rgba(7, 21, 33, 0.68);
  --panel-strong: rgba(6, 18, 29, 0.9);
  --line: rgba(196, 232, 238, 0.18);
  --text: #f2f7f5;
  --muted: #a9c0c8;
  --gold: #f3d998;
  --gold-deep: #c9a65a;
  --teal: #8cf0dd;
  --teal-deep: #31b8ad;
  --fire: #ffa267;
  --fire-deep: #e2603a;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #06131e;
  color: var(--text);
  font-family: 'Manrope', 'Segoe UI', system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
kbd {
  font-family: 'Manrope', sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 2px 6px;
  border-radius: 5px;
  border: 1px solid rgba(220, 245, 245, 0.28);
  background: rgba(255, 255, 255, 0.09);
  color: #eaf7f4;
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.3);
}

.hidden { display: none !important; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at center, transparent 52%, rgba(3, 12, 20, 0.34) 100%),
    linear-gradient(to bottom, rgba(4, 15, 24, 0.12), transparent 22%, transparent 78%, rgba(4, 15, 24, 0.2));
}

#flash {
  position: fixed;
  inset: 0;
  background: #fff;
  opacity: 0;
  pointer-events: none;
  z-index: 30;
  transition: opacity 0.35s ease;
}
#flash.on { opacity: 0.75; transition: none; }

#low-hp {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  opacity: 0;
  transition: opacity 0.4s;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(180, 18, 24, 0.55) 100%);
}
#low-hp.on { opacity: 1; animation: pulseHp 1.6s ease-in-out infinite; }
@keyframes pulseHp { 50% { opacity: 0.55; } }

/* ============ GENERIC OVERLAY ============ */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.36em;
  color: var(--gold);
  text-transform: uppercase;
}
.eyebrow span { width: 26px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold-deep)); display: inline-block; }
.eyebrow span:last-child { background: linear-gradient(90deg, var(--gold-deep), transparent); }

.btn-primary {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 16px 34px;
  border-radius: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #1a1c16;
  background: linear-gradient(135deg, #fff0bf 0%, #f2d28c 46%, #d3ab5f 100%);
  border: 1px solid rgba(255, 250, 225, 0.7);
  box-shadow: 0 10px 30px rgba(205, 160, 70, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.8);
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s;
}
.btn-primary::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 25%, rgba(255, 255, 255, 0.55) 48%, transparent 62%);
  transform: translateX(-130%);
  transition: transform 0.6s ease;
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 16px 40px rgba(205, 160, 70, 0.42); filter: brightness(1.05); }
.btn-primary:hover::after { transform: translateX(130%); }
.btn-primary:active { transform: translateY(0); }
.btn-primary svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.btn-ghost {
  padding: 13px 20px;
  border-radius: 7px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.045);
  color: var(--muted);
  font-size: 13px;
  font-weight: 600;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}
.btn-ghost:hover { background: rgba(255, 255, 255, 0.1); color: var(--text); border-color: rgba(220, 245, 245, 0.4); }
.btn-ghost b { color: var(--gold); }

/* ============ LOADING ============ */
.loading {
  background:
    radial-gradient(circle at 50% 46%, rgba(35, 94, 100, 0.34), transparent 44%),
    linear-gradient(160deg, #061420, #0a2231 55%, #061420);
  z-index: 60;
}
.loading-inner { text-align: center; width: min(360px, 80vw); }
.sigil {
  font-size: 34px;
  color: var(--gold);
  animation: spinSlow 7s linear infinite;
  text-shadow: 0 0 30px rgba(243, 217, 152, 0.7);
}
.loading h2 {
  font-family: 'Cinzel', serif;
  letter-spacing: 0.32em;
  font-size: 22px;
  margin: 12px 0 6px;
  font-weight: 600;
}
#loading-text { font-size: 12px; color: var(--muted); letter-spacing: 0.08em; margin: 0 0 22px; }
.loading-bar { height: 2px; background: rgba(255, 255, 255, 0.1); overflow: hidden; border-radius: 2px; }
#loading-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--teal-deep), var(--gold));
  box-shadow: 0 0 16px var(--gold);
  transition: width 0.4s ease;
}
@keyframes spinSlow { to { transform: rotate(360deg); } }

/* ============ TITLE ============ */
.title {
  z-index: 50;
  justify-content: flex-start;
  overflow: hidden;
  animation: titleIn 1s ease both;
}
@keyframes titleIn { from { opacity: 0; } }
.title-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(100deg, rgba(4, 16, 26, 0.93) 0%, rgba(4, 16, 26, 0.72) 38%, rgba(4, 16, 26, 0.1) 68%, rgba(4, 16, 26, 0.25) 100%),
    linear-gradient(to top, rgba(4, 14, 22, 0.82), transparent 45%);
  pointer-events: none;
}
.title-card {
  position: relative;
  z-index: 3;
  margin-left: max(7vw, 40px);
  max-width: 560px;
  padding: 40px 0;
  animation: cardIn 1.1s cubic-bezier(0.2, 0.7, 0.2, 1) both 0.15s;
}
@keyframes cardIn { from { opacity: 0; transform: translateY(26px); } }
.title-card .eyebrow { margin-bottom: 14px; }
.title h1 {
  font-family: 'Cinzel', serif;
  font-size: clamp(58px, 9vw, 118px);
  line-height: 0.92;
  letter-spacing: 0.11em;
  margin: 0 0 4px -6px;
  font-weight: 600;
  background: linear-gradient(180deg, #fffdf4 10%, #f7e6b5 48%, #c6a662 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 20px 80px rgba(243, 217, 152, 0.24);
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.4));
}
.subtitle {
  font-family: 'Cinzel', serif;
  font-size: clamp(16px, 2vw, 23px);
  letter-spacing: 0.52em;
  color: var(--teal);
  margin: 6px 0 28px 4px;
  font-weight: 500;
  text-shadow: 0 0 28px rgba(140, 240, 221, 0.4);
}
.blurb {
  max-width: 400px;
  font-size: 14px;
  line-height: 1.85;
  color: #c4d7d9;
  margin: 0 0 32px 4px;
}
#btn-start { margin-left: 4px; min-width: 246px; font-size: 15px; }
.title-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  margin: 28px 0 0 4px;
  font-size: 10.5px;
  color: #93adb4;
  letter-spacing: 0.04em;
}
.title-keys span { display: inline-flex; align-items: center; gap: 7px; }
.title-footer {
  position: absolute;
  z-index: 3;
  bottom: max(22px, var(--safe-bottom));
  left: max(7vw, 40px);
  right: 40px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  letter-spacing: 0.16em;
  color: rgba(180, 205, 210, 0.5);
  text-transform: uppercase;
}
.title-footer .dot { width: 5px; height: 5px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 8px var(--teal); }
.title-footer .credit { margin-left: auto; }

.wind-lines { position: absolute; inset: 0; z-index: 2; pointer-events: none; overflow: hidden; }
.wind-lines span {
  position: absolute;
  height: 1px;
  border-radius: 50%;
  background: linear-gradient(90deg, transparent, rgba(190, 255, 243, 0.55), transparent);
  filter: drop-shadow(0 0 6px rgba(140, 240, 221, 0.6));
  animation: windDrift linear infinite;
  opacity: 0;
}
.wind-lines span:nth-child(1) { top: 18%; left: -10%; width: 34%; animation-duration: 9s; animation-delay: 0.2s; }
.wind-lines span:nth-child(2) { top: 35%; left: -25%; width: 22%; animation-duration: 12s; animation-delay: 2.4s; }
.wind-lines span:nth-child(3) { top: 62%; left: -15%; width: 40%; animation-duration: 14s; animation-delay: 1.1s; }
.wind-lines span:nth-child(4) { top: 78%; left: -20%; width: 28%; animation-duration: 10s; animation-delay: 4s; }
.wind-lines span:nth-child(5) { top: 46%; left: -30%; width: 18%; animation-duration: 8s; animation-delay: 5.2s; }
.wind-lines span:nth-child(6) { top: 88%; left: -10%; width: 36%; animation-duration: 13s; animation-delay: 3.3s; }
@keyframes windDrift {
  0% { transform: translateX(0) translateY(0); opacity: 0; }
  10% { opacity: 0.75; }
  70% { opacity: 0.35; }
  100% { transform: translateX(125vw) translateY(-26px); opacity: 0; }
}

/* ============ HUD ============ */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; }
#hud > * { pointer-events: auto; }

#party {
  position: absolute;
  top: max(18px, var(--safe-top));
  left: max(18px, var(--safe-left));
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.char-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 212px;
  padding: 7px 9px 7px 7px;
  border-radius: 34px 9px 9px 34px;
  border: 1px solid transparent;
  background: linear-gradient(90deg, rgba(7, 22, 34, 0.82), rgba(7, 22, 34, 0.5));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition: transform 0.2s, border-color 0.2s, background 0.2s;
  text-align: left;
}
.char-chip:hover { transform: translateX(3px); }
.char-chip.active {
  border-color: rgba(243, 217, 152, 0.55);
  background: linear-gradient(90deg, rgba(24, 51, 60, 0.92), rgba(9, 26, 39, 0.62));
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.3), inset 0 0 24px rgba(140, 240, 221, 0.06);
}
.char-chip.active .char-name { color: #fff; }
.char-chip .portrait {
  position: relative;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: 'Cinzel', serif;
  font-size: 17px;
  font-weight: 700;
  color: #062028;
  border: 1.5px solid rgba(255, 255, 255, 0.6);
  overflow: hidden;
}
.portrait.aria { background: radial-gradient(circle at 32% 26%, #e7fffa, #7ee6d4 45%, #1f8c8d 90%); }
.portrait.ember { background: radial-gradient(circle at 32% 26%, #fff0d8, #ffae67 44%, #b33c26 92%); }
.portrait span { transform: translateY(1px); text-shadow: 0 1px 0 rgba(255, 255, 255, 0.4); }
.char-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.char-name { font-size: 11px; font-weight: 700; letter-spacing: 0.03em; color: #dce9e9; display: flex; align-items: center; gap: 6px; }
.char-name em { font-style: normal; font-size: 8.5px; letter-spacing: 0.12em; color: var(--teal); text-transform: uppercase; }
.char-chip[data-char="1"] .char-name em { color: var(--fire); }
.char-hp { height: 3px; border-radius: 3px; background: rgba(255, 255, 255, 0.14); overflow: hidden; }
.char-hp i { display: block; height: 100%; width: 100%; border-radius: 3px; background: linear-gradient(90deg, #63d8a2, #b6f2b9); transition: width 0.25s; }
.char-chip[data-char="1"] .char-hp i { background: linear-gradient(90deg, #e88f52, #ffd08a); }
.char-chip kbd { opacity: 0.55; font-size: 9px; padding: 1px 5px; }
.char-chip.active kbd { opacity: 1; border-color: var(--gold-deep); color: var(--gold); }

#quest-card {
  position: absolute;
  top: max(172px, calc(var(--safe-top) + 168px));
  left: max(18px, var(--safe-left));
  width: 236px;
  padding: 13px 15px 14px;
  border-radius: 9px;
  background: linear-gradient(135deg, rgba(7, 22, 34, 0.78), rgba(7, 22, 34, 0.48));
  border: 1px solid var(--line);
  border-left: 2px solid var(--gold-deep);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.25);
}
.quest-head { display: flex; align-items: center; gap: 7px; font-size: 8.5px; letter-spacing: 0.22em; font-weight: 800; color: var(--gold); margin-bottom: 7px; }
.quest-diamond { font-size: 8px; color: var(--gold); filter: drop-shadow(0 0 5px rgba(243, 217, 152, 0.8)); }
#quest-title { font-size: 13px; font-weight: 700; line-height: 1.35; color: #f3fafe; }
#quest-desc { font-size: 10.5px; line-height: 1.55; color: #9fb7bd; margin-top: 4px; }
#quest-progress { display: flex; align-items: center; gap: 8px; margin-top: 9px; }
#quest-progress i { height: 2px; flex: 1; background: rgba(255, 255, 255, 0.12); border-radius: 2px; overflow: hidden; position: relative; }
#quest-progress i::after { content: ''; display: block; height: 100%; width: var(--p, 0%); background: linear-gradient(90deg, var(--teal-deep), var(--gold)); transition: width 0.4s; }
#quest-progress span { font-size: 9.5px; color: var(--gold); font-weight: 700; letter-spacing: 0.06em; }

#minimap-wrap {
  position: absolute;
  top: max(18px, var(--safe-top));
  right: max(18px, var(--safe-right));
  width: 168px;
  height: 168px;
  border-radius: 50%;
}
#minimap {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: block;
  background: rgba(5, 20, 30, 0.8);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4);
}
.minimap-ring {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid rgba(243, 217, 152, 0.38);
  pointer-events: none;
}
.minimap-ring::before {
  content: '';
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 1px dashed rgba(200, 235, 235, 0.15);
}
.minimap-n {
  position: absolute;
  top: -11px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--gold);
  background: #0a1c29;
  padding: 1px 7px;
  border-radius: 10px;
  border: 1px solid rgba(243, 217, 152, 0.4);
}
.minimap-label {
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: rgba(230, 245, 245, 0.65);
  text-transform: uppercase;
  white-space: nowrap;
  text-shadow: 0 1px 4px #000;
}

#boss-bar {
  position: absolute;
  top: max(22px, var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  width: min(390px, 52vw);
}
.boss-head { display: flex; align-items: baseline; justify-content: center; gap: 9px; margin-bottom: 6px; text-shadow: 0 2px 8px #000; }
.boss-head span { font-family: 'Cinzel', serif; font-size: 14px; letter-spacing: 0.1em; color: #ffe6d3; }
.boss-head em { font-style: normal; font-size: 8px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--teal); }
.boss-track { height: 7px; border-radius: 4px; background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255, 255, 255, 0.22); padding: 1px; }
#boss-fill { display: block; height: 100%; width: 100%; border-radius: 3px; background: linear-gradient(90deg, #3aa9d4, #8fe6f7); box-shadow: 0 0 12px rgba(80, 190, 230, 0.7); transition: width 0.25s; }

.world-marker {
  position: absolute;
  transform: translate(-50%, -100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.8));
}
.marker-diamond {
  width: 13px;
  height: 13px;
  background: var(--gold);
  transform: rotate(45deg);
  border: 2px solid rgba(255, 255, 255, 0.85);
  box-shadow: 0 0 16px rgba(243, 217, 152, 0.9);
  animation: markerBob 1.8s ease-in-out infinite;
}
.marker-dist { font-size: 9px; font-weight: 700; letter-spacing: 0.08em; color: #fff; background: rgba(5, 18, 28, 0.7); padding: 2px 7px; border-radius: 8px; }
@keyframes markerBob { 50% { transform: rotate(45deg) translate(-2px, -2px); } }

#stamina-wrap {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  width: min(240px, 30vw);
  pointer-events: none;
  opacity: 0.95;
  transition: opacity 0.3s;
}
#stamina { height: 4px; border-radius: 3px; background: rgba(0, 0, 0, 0.45); overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.14); }
#stamina i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #8cf0dd, #f3d998); border-radius: 3px; transition: width 0.1s linear; }

#interact {
  position: absolute;
  left: 50%;
  bottom: clamp(96px, 16vh, 160px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px 9px 9px;
  background: rgba(6, 19, 29, 0.82);
  border: 1px solid rgba(243, 217, 152, 0.38);
  border-radius: 30px;
  backdrop-filter: blur(8px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
  animation: interactIn 0.25s ease both;
}
@keyframes interactIn { from { opacity: 0; transform: translate(-50%, 8px); } }
#interact .key {
  width: 28px; height: 28px;
  display: grid; place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, #fff2c9, #d9b269);
  color: #14232a;
  font-size: 12px;
  font-weight: 800;
  box-shadow: 0 0 14px rgba(243, 217, 152, 0.4);
}
#interact-text { font-size: 12px; font-weight: 600; letter-spacing: 0.02em; color: #eefafa; }

#abilities {
  position: absolute;
  right: max(26px, var(--safe-right));
  bottom: max(26px, calc(var(--safe-bottom) + 18px));
  width: 224px;
  height: 196px;
  --accent: var(--teal);
  --accent-deep: var(--teal-deep);
}
body.pyro #abilities { --accent: var(--fire); --accent-deep: var(--fire-deep); }
.ability {
  position: absolute;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #f4fffd;
  background: radial-gradient(circle at 34% 28%, rgba(255, 255, 255, 0.22), rgba(10, 32, 44, 0.9) 62%);
  border: 1px solid rgba(220, 250, 248, 0.32);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4), inset 0 0 22px rgba(140, 240, 221, 0.12);
  transition: transform 0.10s ease, box-shadow 0.2s, border-color 0.2s;
  touch-action: none;
  overflow: hidden;
}
.ability:hover { transform: scale(1.04); border-color: rgba(255, 255, 255, 0.55); }
.ability:active { transform: scale(0.94); }
.ability .icon { width: 45%; height: 45%; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; stroke-linecap: round; }
.ability .key-cap {
  position: absolute;
  bottom: 5px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: rgba(220, 245, 245, 0.7);
  text-transform: uppercase;
  white-space: nowrap;
}
.ability .cd {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 0%;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12%;
  background: rgba(1, 9, 15, 0.74);
  color: #fff;
  font-size: 15px;
  font-weight: 800;
  border-radius: 0;
  pointer-events: none;
  transition: height 0.1s linear;
}
.ability .cd:empty { display: none; }
#btn-attack { right: 0; bottom: 0; width: 88px; height: 88px; }
#btn-attack .icon { width: 50%; height: 50%; }
#btn-attack .key-cap { display: none; }
#btn-skill { right: 100px; bottom: 4px; width: 62px; height: 62px; border-color: rgba(140, 240, 221, 0.42); }
#btn-burst { right: 112px; bottom: 88px; width: 57px; height: 57px; border-color: rgba(243, 217, 152, 0.42); color: var(--gold); }
#btn-burst .icon { width: 42%; height: 42%; fill: rgba(243, 217, 152, 0.2); stroke: var(--gold); }
#btn-jump { right: 10px; bottom: 110px; width: 56px; height: 56px; }
#btn-jump .key-cap { display: none; }
#btn-skill.ready { box-shadow: 0 0 24px color-mix(in srgb, var(--accent) 38%, transparent), inset 0 0 22px rgba(140, 240, 221, 0.12); }
#btn-burst.ready { box-shadow: 0 0 28px rgba(243, 217, 152, 0.55), inset 0 0 24px rgba(243, 217, 152, 0.18); animation: burstPulse 2.2s ease-in-out infinite; }
@keyframes burstPulse { 50% { box-shadow: 0 0 40px rgba(243, 217, 152, 0.85), inset 0 0 30px rgba(243, 217, 152, 0.3); } }
.energy-pip {
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: conic-gradient(var(--gold) var(--energy, 0%), transparent 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  opacity: 0.85;
  pointer-events: none;
}

#joystick {
  position: absolute;
  left: max(30px, calc(var(--safe-left) + 20px));
  bottom: max(34px, calc(var(--safe-bottom) + 26px));
  width: 116px;
  height: 116px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(9, 28, 42, 0.32) 0%, rgba(9, 28, 42, 0.55) 100%);
  border: 1px solid rgba(210, 245, 245, 0.22);
  backdrop-filter: blur(3px);
  display: none;
  touch-action: none;
}
#joystick-ring { position: absolute; inset: 9px; border-radius: 50%; border: 1px dashed rgba(220, 250, 250, 0.16); }
#stick {
  position: absolute;
  left: 50%; top: 50%;
  width: 48px; height: 48px;
  margin: -24px 0 0 -24px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(240, 255, 252, 0.75), rgba(120, 210, 200, 0.38) 68%);
  border: 1px solid rgba(240, 255, 255, 0.5);
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.35);
  transition: transform 0.05s linear;
}

#controls-hint {
  position: absolute;
  left: max(18px, var(--safe-left));
  bottom: max(20px, calc(var(--safe-bottom) + 12px));
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  max-width: 40vw;
  font-size: 9.5px;
  color: rgba(205, 228, 230, 0.55);
  letter-spacing: 0.03em;
}
#controls-hint span { display: inline-flex; align-items: center; gap: 5px; }
#controls-hint kbd { opacity: 0.7; }
#btn-pause {
  position: absolute;
  top: max(20px, var(--safe-top));
  right: max(200px, calc(var(--safe-right) + 196px));
  width: 34px; height: 34px;
  border-radius: 50%;
  display: grid; place-items: center;
  font-size: 9px;
  letter-spacing: 0;
  color: rgba(230, 245, 245, 0.65);
  background: rgba(7, 21, 33, 0.6);
  border: 1px solid var(--line);
  backdrop-filter: blur(6px);
  transition: color 0.2s, border-color 0.2s;
}
#btn-pause:hover { color: var(--gold); border-color: var(--gold-deep); }

#toast-stack {
  position: absolute;
  top: max(210px, calc(var(--safe-top) + 200px));
  right: max(30px, var(--safe-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 14px;
  border-radius: 7px;
  background: rgba(6, 20, 30, 0.72);
  border: 1px solid rgba(243, 217, 152, 0.22);
  border-right: 2px solid var(--gold);
  backdrop-filter: blur(8px);
  font-size: 11px;
  color: #eaf7f5;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
  animation: toastIn 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.toast.out { animation: toastOut 0.4s ease both; }
.toast b { color: var(--gold); }
@keyframes toastIn { from { opacity: 0; transform: translateX(22px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(22px); } }

#damage-layer { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.dmg {
  position: absolute;
  transform: translate(-50%, -50%);
  font-weight: 800;
  font-size: 20px;
  color: #fff;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.45), 0 0 14px rgba(255, 255, 255, 0.35);
  animation: dmgFloat 0.95s ease-out forwards;
  white-space: nowrap;
  letter-spacing: -0.02em;
}
.dmg.crit { font-size: 27px; color: #ffe7a1; text-shadow: 0 2px 0 rgba(80, 40, 0, 0.5), 0 0 20px rgba(255, 210, 110, 0.7); }
.dmg.heal { color: #a6f5b9; font-size: 17px; }
.dmg.reaction { font-size: 15px; color: #ffd08a; letter-spacing: 0.06em; }
@keyframes dmgFloat {
  0% { opacity: 0; margin-top: 6px; transform: translate(-50%, -50%) scale(0.7); }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1.08); }
  100% { opacity: 0; margin-top: -62px; transform: translate(-50%, -50%) scale(0.92); }
}

#enemy-bars { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.enemy-bar {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 74px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  transition: opacity 0.2s;
}
.enemy-bar .eb-name { font-size: 7.5px; letter-spacing: 0.06em; color: #e9f6f6; text-shadow: 0 1px 3px #000; white-space: nowrap; }
.enemy-bar .eb-track { width: 100%; height: 4px; padding: 1px; background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255, 255, 255, 0.18); border-radius: 3px; }
.enemy-bar .eb-fill { height: 100%; border-radius: 2px; background: linear-gradient(90deg, #89dfc8, #d8ffef); transition: width 0.18s; }
.enemy-bar.boss { width: 130px; }
.enemy-bar.boss .eb-name { color: #ffe2ce; font-size: 8.5px; }

#reaction-pop {
  position: absolute;
  left: 50%;
  top: 31%;
  transform: translate(-50%, -50%);
  font-family: 'Cinzel', serif;
  font-size: clamp(22px, 3.2vw, 34px);
  letter-spacing: 0.16em;
  color: #ffe7bd;
  text-shadow: 0 0 24px rgba(255, 170, 90, 0.85), 0 2px 6px rgba(0, 0, 0, 0.7);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
}
#reaction-pop.show { animation: reactionPop 1.5s ease-out both; }
@keyframes reactionPop {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.7); letter-spacing: 0.3em; }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  72% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -58%) scale(1.02); }
}

/* ============ DIALOGUE ============ */
#dialogue {
  position: fixed;
  z-index: 32;
  left: 50%;
  bottom: max(24px, calc(var(--safe-bottom) + 16px));
  transform: translateX(-50%);
  width: min(780px, calc(100vw - 48px));
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 18px;
  border-radius: 11px;
  background: linear-gradient(135deg, rgba(8, 24, 36, 0.94), rgba(10, 30, 42, 0.88));
  border: 1px solid rgba(243, 217, 152, 0.26);
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px);
  animation: dialogueIn 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes dialogueIn { from { opacity: 0; transform: translate(-50%, 18px); } }
.dialogue-portrait {
  flex: 0 0 58px;
  width: 58px; height: 58px;
  border-radius: 50%;
  display: grid; place-items: center;
  font-family: 'Cinzel', serif;
  font-size: 22px;
  color: #10242b;
  background: radial-gradient(circle at 34% 28%, #fff5d8, #d8c193 50%, #a28757);
  border: 1.5px solid rgba(255, 245, 220, 0.8);
  box-shadow: 0 0 24px rgba(243, 217, 152, 0.25);
}
.dialogue-main { flex: 1; min-width: 0; }
.dialogue-name { font-family: 'Cinzel', serif; font-size: 12px; letter-spacing: 0.14em; color: var(--gold); margin-bottom: 5px; }
#dialogue-text { margin: 0; font-size: 13px; line-height: 1.65; color: #e4f0ef; min-height: 42px; }
.dialogue-next {
  flex: 0 0 auto;
  align-self: flex-end;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--gold);
  border: 1px solid rgba(243, 217, 152, 0.3);
  background: rgba(243, 217, 152, 0.07);
  transition: background 0.2s;
}
.dialogue-next:hover { background: rgba(243, 217, 152, 0.16); }
.dialogue-next span { animation: nudge 1.2s ease-in-out infinite; }
@keyframes nudge { 50% { transform: translateX(3px); } }

/* ============ REWARD / PAUSE / DEATH ============ */
#reward, #pause, #death { background: rgba(3, 10, 16, 0.72); backdrop-filter: blur(9px); z-index: 45; }
#reward { z-index: 46; }
.reward-card {
  position: relative;
  width: min(620px, calc(100vw - 40px));
  padding: 40px 40px 34px;
  text-align: center;
  border-radius: 14px;
  background: radial-gradient(ellipse at top, rgba(50, 74, 70, 0.75), rgba(7, 21, 33, 0.96) 65%);
  border: 1px solid rgba(243, 217, 152, 0.32);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.6), inset 0 0 80px rgba(243, 217, 152, 0.05);
  overflow: hidden;
  animation: rewardIn 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes rewardIn { from { opacity: 0; transform: translateY(22px) scale(0.97); } }
.reward-rays {
  position: absolute;
  inset: -60% -20%;
  background: conic-gradient(from 0deg, transparent 0 8deg, rgba(243, 217, 152, 0.07) 8deg 10deg, transparent 10deg 24deg);
  animation: spinSlow 40s linear infinite;
  pointer-events: none;
}
.reward-card > * { position: relative; }
.reward-card .eyebrow { justify-content: center; margin-bottom: 10px; }
.reward-card h2 { font-family: 'Cinzel', serif; font-size: 29px; letter-spacing: 0.08em; color: #fff6dd; margin: 0 0 26px; }
.loot-row { display: flex; gap: 12px; justify-content: center; margin-bottom: 30px; }
.loot {
  flex: 1;
  max-width: 150px;
  padding: 16px 10px 13px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(243, 217, 152, 0.18);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.loot-icon { width: 48px; height: 48px; display: grid; place-items: center; font-size: 25px; border-radius: 10px; margin-bottom: 5px; }
.loot-icon.sword { color: #bfeaff; background: radial-gradient(circle, rgba(110, 190, 220, 0.35), transparent 70%); }
.loot-icon.gem { color: var(--gold); background: radial-gradient(circle, rgba(243, 217, 152, 0.3), transparent 70%); }
.loot-icon.wing { color: var(--teal); background: radial-gradient(circle, rgba(140, 240, 221, 0.3), transparent 70%); }
.loot span { font-size: 11px; font-weight: 700; color: #eaf6f4; line-height: 1.3; }
.loot em { font-style: normal; font-size: 8.5px; color: var(--muted); letter-spacing: 0.05em; }

.pause-card {
  width: min(540px, calc(100vw - 40px));
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  padding: 34px 36px;
  border-radius: 14px;
  background: linear-gradient(160deg, rgba(12, 34, 46, 0.97), rgba(6, 19, 29, 0.98));
  border: 1px solid rgba(196, 232, 238, 0.18);
  box-shadow: var(--shadow);
}
.pause-card .eyebrow { margin-bottom: 8px; }
.pause-card h2 { font-family: 'Cinzel', serif; font-size: 32px; letter-spacing: 0.14em; margin: 0 0 24px; color: #f7efd8; }
.pause-actions { display: flex; flex-direction: column; gap: 9px; margin-bottom: 26px; }
.pause-actions .btn-primary { width: 100%; }
.pause-controls {
  display: grid;
  gap: 8px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  font-size: 11.5px;
  color: var(--muted);
}
.pause-controls kbd { margin-right: 4px; }
.pause-controls div:last-child { color: var(--teal); }

.death-inner { text-align: center; }
