    pivot.add(cuff);
    body.add(pivot);
    legs.push(pivot);
  }

  // ---- torso ----
  const hips = new THREE.Mesh(new THREE.CapsuleGeometry(0.21, 0.16, 3, 8), outfitDarkMat);
  hips.position.y = 0.98;
  hips.scale.z = 0.8;
  body.add(hips);

  const torso = capsule(0.235, 0.34, outfitMat);
