  // ---- arms ----
  const arms = [];
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group();
    pivot.position.set(side * 0.3, 1.48, 0);
    const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 7), outfitMat);
