    const fore = capsule(0.06, 0.24, clothMat);
    fore.position.y = -0.43;
    pivot.add(fore);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.068, 8, 7), skinMat);
    hand.position.y = -0.62;
    hand.castShadow = true;
    pivot.add(hand);
    const cuff = new THREE.Mesh(new THREE.TorusGeometry(0.065, 0.018, 4, 10), trimMat);
    cuff.rotation.x = Math.PI / 2;
    cuff.position.y = -0.33;
    pivot.add(cuff);
    body.add(pivot);
    arms.push(pivot);
    pivot.userData.hand = hand;
  }

  // ---- sword (right hand) ----
  const sword = new THREE.Group();
  sword.position.y = -0.64;
  const bladeMat = new THREE.MeshToonMaterial({
    color: data.sword,
    emissive: new THREE.Color(data.swordGlow),
    emissiveIntensity: 0.28,
    gradientMap: undefined,
  });
  const blade = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.86, 0.018), bladeMat);
  blade.position.y = -0.45;
  blade.castShadow = true;
  sword.add(blade);
  const tip = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.16, 4), bladeMat);
  tip.position.y = -0.94;
  tip.rotation.x = Math.PI;
  sword.add(tip);
  const guard = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.035, 0.05), trimMat);
  guard.position.y = -0.01;
  sword.add(guard);
  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.03, 0.16, 6), toon('#3c2b25'));
  grip.position.y = 0.08;
  sword.add(grip);
  const pommel = new THREE.Mesh(new THREE.SphereGeometry(0.038, 6, 5), trimMat);
  pommel.position.y = 0.17;
  sword.add(pommel);
  const bladeGlow = new THREE.Sprite(
    new THREE.SpriteMaterial({
      color: data.swordGlow,
      transparent: true,
      opacity: 0.35,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      map: (() => {
        const c = document.createElement('canvas');
        c.width = c.height = 64;
        const ctx = c.getContext('2d');
        const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
        g.addColorStop(0, 'rgba(255,255,255,0.9)');
        g.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, 64, 64);
        return new THREE.CanvasTexture(c);
      })(),
    })
  );
  bladeGlow.scale.set(0.42, 1.4, 1);
  bladeGlow.position.y = -0.5;
  sword.add(bladeGlow);
  arms[1].add(sword);

  // ---- head ----
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.1, 7), skinMat);
  neck.position.y = 1.57;
  body.add(neck);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.225, 16, 14), skinMat);
  head.position.y = 1.79;
  head.scale.set(0.94, 1, 0.96);
  head.castShadow = true;
  body.add(head);

  const jaw = new THREE.Mesh(new THREE.SphereGeometry(0.19, 12, 10), skinMat);
  jaw.position.set(0, 1.71, 0.035);
  jaw.scale.set(0.9, 0.9, 0.9);
  body.add(jaw);

  // eyes + brows give the tiny face some life.
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.026, 8, 6), eyeMat);
    eye.position.set(side * 0.077, 1.815, 0.2);
    eye.scale.set(0.85, 1.25, 0.5);
    body.add(eye);
    const shine = new THREE.Mesh(new THREE.SphereGeometry(0.009, 5, 4), new THREE.MeshBasicMaterial({ color: '#ffffff' }));
    shine.position.set(side * 0.083, 1.824, 0.22);
    body.add(shine);
    const brow = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.012, 0.01), hairDarkMat);
    brow.position.set(side * 0.077, 1.875, 0.205);
    brow.rotation.z = side * -0.12;
    body.add(brow);
  }
  const mouth = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.008, 0.01), toon('#a5554f'));
  mouth.position.set(0, 1.71, 0.215);
  body.add(mouth);

  // hair cap
  const hairCap = new THREE.Mesh(new THREE.SphereGeometry(0.24, 15, 12, 0, Math.PI * 2, 0, Math.PI * 0.68), hairMat);
  hairCap.position.set(0, 1.81, -0.012);
  hairCap.scale.set(1.02, 1.05, 1.03);
  hairCap.castShadow = true;
  body.add(hairCap);

  const bangs = new THREE.Group();
  for (const side of [-1, 1]) {
    const bang = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.3, 5), hairMat);
    bang.position.set(side * 0.1, 1.79, 0.19);
    bang.rotation.set(0.32, 0, side * 0.2);
    bangs.add(bang);
  }
  const bangCenter = new THREE.Mesh(new THREE.ConeGeometry(0.065, 0.24, 5), hairMat);
  bangCenter.position.set(0.01, 1.83, 0.215);
  bangCenter.rotation.x = 0.24;
  bangs.add(bangCenter);
  body.add(bangs);

  // long back hair + ponytail
  const backHair = new THREE.Mesh(new THREE.CapsuleGeometry(0.16, 0.5, 4, 8), hairMat);
  backHair.position.set(0, 1.57, -0.13);
  backHair.scale.z = 0.7;
  body.add(backHair);

  const ponytailPivot = new THREE.Group();
  ponytailPivot.position.set(0, 1.86, -0.2);
  const ponytail = new THREE.Mesh(new THREE.CapsuleGeometry(0.075, 0.5, 4, 7), hairMat);
  ponytail.position.y = -0.27;
  ponytailPivot.add(ponytail);
  const tailTip = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.26, 5), hairDarkMat);
  tailTip.position.y = -0.62;
  tailTip.rotation.x = Math.PI;
  ponytailPivot.add(tailTip);
  const hairTie = new THREE.Mesh(new THREE.TorusGeometry(0.07, 0.02, 4, 9), trimMat);
  hairTie.rotation.x = Math.PI / 2;
  hairTie.position.y = -0.02;
  ponytailPivot.add(hairTie);
  body.add(ponytailPivot);

  // head accessory: Aria gets a wind feather, Ember a small ember ornament.
  if (data.element === 'anemo') {
    const feather = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.38, 4), trimMat);
    feather.position.set(0.2, 1.98, -0.05);
    feather.rotation.set(0.1, 0, -0.75);
    body.add(feather);
  } else {
    const emberGem = new THREE.Mesh(new THREE.OctahedronGeometry(0.06, 0), new THREE.MeshBasicMaterial({ color: '#ffcf7a' }));
    emberGem.position.set(0.2, 1.94, 0.02);
    body.add(emberGem);
  }

  // ---- cape / scarf ----
  const capePivot = new THREE.Group();
  capePivot.position.set(0, 1.47, -0.16);
  const capeMat = toon(data.cape, { side: THREE.DoubleSide });
  const cape = new THREE.Mesh(makeCapeGeometry(0.58, 1.05), capeMat);
  cape.position.y = -0.52;
  cape.castShadow = true;
  capePivot.add(cape);
  const capeTrim = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.03, 0.02), trimMat);
  capeTrim.position.set(0, -1.02, -0.02);
  capePivot.add(capeTrim);
  body.add(capePivot);

  const scarf = new THREE.Mesh(new THREE.TorusGeometry(0.17, 0.045, 5, 14), toon(data.color, { emissive: new THREE.Color(data.color), emissiveIntensity: 0.1 }));
  scarf.rotation.x = Math.PI / 2;
  scarf.position.y = 1.55;
  scarf.scale.z = 0.9;
  body.add(scarf);

  const aura = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: (() => {
        const c = document.createElement('canvas');
        c.width = c.height = 64;
        const ctx = c.getContext('2d');
        const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
        g.addColorStop(0, 'rgba(255,255,255,0.45)');
        g.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, 64, 64);
        return new THREE.CanvasTexture(c);
      })(),
      color: data.color,
      transparent: true,
      opacity: 0.22,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
  );
  aura.scale.setScalar(2.6);
  aura.position.y = 1.05;
  body.add(aura);

  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.42, 18),
    new THREE.MeshBasicMaterial({ color: '#081512', transparent: true, opacity: 0.28, depthWrite: false })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.02;
  root.add(shadow);

  const anim = {
    phase: 0,
    idle: Math.random() * 6,
    attack: -1,
    cast: -1,
    hurt: 0,
    glideBlend: 0,
    swimBlend: 0,
    lean: 0,
    attackKind: 'slash',
  };

  function update(dt, state) {
    const {
      speed = 0,
      onGround = true,
      gliding = false,
      swimming = false,
      elapsed = 0,
    } = state;

    const moveBlend = clamp(speed / 5.6, 0, 1.35);
    const stride = 0.55 + Math.min(speed, 9) * 0.055;
    if (onGround && !swimming && speed > 0.2) {
      anim.phase += dt * (5.5 + speed * 0.95);
    } else {
      anim.phase += dt * 1.5;
    }
    anim.glideBlend = damp(anim.glideBlend, gliding ? 1 : 0, 7, dt);
    anim.swimBlend = damp(anim.swimBlend, swimming ? 1 : 0, 6, dt);

    const swing = Math.sin(anim.phase);
    const legSwing = onGround ? swing * stride * moveBlend * (1 - anim.glideBlend) : 0.08;
    legs[0].rotation.x = legSwing;
    legs[1].rotation.x = -legSwing;
    legs[0].rotation.z = 0.02;
    legs[1].rotation.z = -0.02;

    const armSwing = -legSwing * 0.72;
    arms[0].rotation.x = armSwing;
    arms[1].rotation.x = -armSwing + (anim.attack >= 0 ? 0 : 0);
    arms[0].rotation.z = 0.1 + anim.glideBlend * 0.95 + anim.swimBlend * 0.5;
    arms[1].rotation.z = -0.1 - anim.glideBlend * 0.95 - anim.swimBlend * 0.5;

    // Attack overrides the sword arm with a quick overhead arc.
    if (anim.attack >= 0) {
      const t = anim.attack;
      const wind = Math.sin(Math.min(t / 0.32, 1) * Math.PI * 0.5);
      const strike = Math.sin(Math.max(0, (t - 0.28) / 0.42) * Math.PI * 0.5);
      const recover = Math.sin(Math.max(0, (t - 0.66) / 0.34) * Math.PI * 0.5);
      arms[1].rotation.x = 0.55 * wind - 2.5 * strike + 1.9 * recover;
      arms[1].rotation.z = -0.35 - 0.4 * wind + 0.7 * strike;
      arms[0].rotation.x = -0.2 + 0.5 * strike;
      arms[0].rotation.z = 0.3 + 0.35 * strike;
      body.rotation.y = 0.38 * wind - 0.62 * strike + 0.2 * recover;
      body.position.x = 0.04 * strike;
      head.rotation.y = -0.1 * strike;
    } else {
      body.rotation.y = damp(body.rotation.y, 0, 14, dt);
      body.position.x = damp(body.position.x, 0, 12, dt);
      head.rotation.y = 0;
      if (anim.cast >= 0) {
        const t = anim.cast;
        const push = Math.sin(clamp(t, 0, 1) * Math.PI);
        arms[0].rotation.x = -1.5 * push;
        arms[1].rotation.x = -1.5 * push;
        arms[0].rotation.z = 0.4 * push + 0.1;
        arms[1].rotation.z = -0.4 * push - 0.1;
        body.rotation.x = -0.08 * push;
      } else {
        body.rotation.x = damp(body.rotation.x, 0, 10, dt);
      }
    }

    if (gliding || swimming) {
      legs[0].rotation.x = gliding ? -0.25 : Math.sin(anim.phase * 1.5) * 0.35;
      legs[1].rotation.x = gliding ? -0.1 : Math.sin(anim.phase * 1.5 + 1.4) * 0.35;
      body.rotation.x = gliding ? -0.18 : 0;
    }

    const breathe = Math.sin(elapsed * 2 + anim.idle) * 0.012;
    body.position.y = breathe + (gliding ? 0.04 : 0) + (swimming ? -0.28 : 0);
    capePivot.rotation.x = -0.1 - moveBlend * 0.28 - anim.glideBlend * 0.45 + Math.sin(elapsed * 2.2 + anim.idle) * 0.025;
    capePivot.rotation.z = Math.sin(anim.phase * 0.5) * 0.05;
    ponytailPivot.rotation.x = 0.08 + moveBlend * 0.3 + anim.glideBlend * 0.5;
    ponytailPivot.rotation.z = Math.sin(elapsed * 1.7 + anim.idle) * 0.08;
    aura.material.opacity = 0.16 + Math.sin(elapsed * 2.6) * 0.05;

    if (anim.hurt > 0) {
      anim.hurt = Math.max(0, anim.hurt - dt * 3);
      body.rotation.z = Math.sin(anim.hurt * 28) * 0.05;
    } else {
      body.rotation.z = damp(body.rotation.z, 0, 10, dt);
    }
  }

  function setVisible(visible) {
    root.visible = visible;
  }

  root.scale.setScalar(1.02);
  return {
    root,
    data,
    anim,
    parts: { legs, arms, head, body, capePivot, ponytailPivot, sword, aura, bladeMat },
    update,
    setVisible,
    getHandPosition(target = new THREE.Vector3()) {
      return arms[1].userData.hand.getWorldPosition(target);
    },
    getSwordTip(target = new THREE.Vector3()) {
      blade.getWorldPosition(target);
      return target;
    },
  };
}

import * as THREE from 'three';
import { glowSprite, clamp } from './look.js';

export const ELEMENT_COLORS = {
  anemo: '#8cf0dd',
  pyro: '#ff9a5c',
  hydro: '#6fc9ff',
  electro: '#c69bff',
  physical: '#fff1cf',
};

const particleVertex = /* glsl */ `
  attribute vec3 aColor;
  attribute float aSize;
  attribute float aAlpha;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * (340.0 / max(1.0, -mvPosition.z));
    gl_Position = projectionMatrix * mvPosition;
    vColor = aColor;
    vAlpha = aAlpha;
  }
`;

const particleFragment = /* glsl */ `
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec2 p = gl_PointCoord - 0.5;
    float d = length(p);
    float a = smoothstep(0.5, 0.03, d) * vAlpha;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor, a);
  }
`;

class Particles {
  constructor(scene, capacity = 700) {
    this.capacity = capacity;
    this.cursor = 0;
    this.geometry = new THREE.BufferGeometry();
    this.positions = new Float32Array(capacity * 3);
    this.colors = new Float32Array(capacity * 3);
    this.sizes = new Float32Array(capacity);
    this.alphas = new Float32Array(capacity);
    this.velocities = new Float32Array(capacity * 3);
    this.life = new Float32Array(capacity);
    this.maxLife = new Float32Array(capacity);
    this.gravity = new Float32Array(capacity);
    this.drag = new Float32Array(capacity);
    this.baseSize = new Float32Array(capacity);

    for (let i = 0; i < capacity; i++) {
      this.positions[i * 3 + 1] = -999;
      this.sizes[i] = 0;
    }

    this.geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    this.geometry.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
    this.geometry.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
    this.geometry.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));

    this.material = new THREE.ShaderMaterial({
      vertexShader: particleVertex,
      fragmentShader: particleFragment,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    this.points = new THREE.Points(this.geometry, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 10;
    scene.add(this.points);
  }

  spawn(position, color, opts = {}) {
    const {
      count = 12,
      speed = 3,
      spread = 1,
      size = 0.3,
      life = 0.7,
      gravity = 7,
      drag = 2.5,
      up = 1.2,
      radius = 0,
    } = opts;
    const c = new THREE.Color(color);
    for (let n = 0; n < count; n++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % this.capacity;
      const angle = Math.random() * Math.PI * 2;
      const r = Math.random() * radius;
      this.positions[i * 3] = position.x + Math.cos(angle) * r;
      this.positions[i * 3 + 1] = position.y + (Math.random() - 0.5) * radius * 0.8;
      this.positions[i * 3 + 2] = position.z + Math.sin(angle) * r;
      const sp = speed * (0.35 + Math.random() * 0.95);
      const dir = new THREE.Vector3(
        Math.cos(angle) * spread,
        up + (Math.random() - 0.5) * spread,
        Math.sin(angle) * spread
      ).normalize().multiplyScalar(sp);
      this.velocities[i * 3] = dir.x;
      this.velocities[i * 3 + 1] = dir.y;
      this.velocities[i * 3 + 2] = dir.z;
      const shade = 0.72 + Math.random() * 0.42;
      this.colors[i * 3] = c.r * shade;
      this.colors[i * 3 + 1] = c.g * shade;
      this.colors[i * 3 + 2] = c.b * shade;
      this.baseSize[i] = size * (0.55 + Math.random() * 1.1);
      this.sizes[i] = this.baseSize[i];
      this.alphas[i] = 0.95;
      this.maxLife[i] = life * (0.65 + Math.random() * 0.8);
      this.life[i] = this.maxLife[i];
      this.gravity[i] = gravity;
      this.drag[i] = drag;
    }
  }

  update(dt) {
    const pos = this.positions;
    const vel = this.velocities;
    for (let i = 0; i < this.capacity; i++) {
      if (this.life[i] <= 0) continue;
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        this.alphas[i] = 0;
        this.sizes[i] = 0;
        pos[i * 3 + 1] = -999;
        continue;
      }
      const drag = Math.max(0, 1 - this.drag[i] * dt);
      vel[i * 3] *= drag;
      vel[i * 3 + 1] = vel[i * 3 + 1] * drag - this.gravity[i] * dt;
      vel[i * 3 + 2] *= drag;
      pos[i * 3] += vel[i * 3] * dt;
      pos[i * 3 + 1] += vel[i * 3 + 1] * dt;
      pos[i * 3 + 2] += vel[i * 3 + 2] * dt;
      const t = this.life[i] / this.maxLife[i];
      this.alphas[i] = Math.min(1, t * 1.7);
      this.sizes[i] = this.baseSize[i] * (0.45 + t * 0.75);
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
  }
}

export class FX {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.particles = new Particles(scene);
    this.effects = [];
    this.damageLayer = document.getElementById('damage-layer');
    this.numbers = [];
    this.projectile = new THREE.Vector3();
  }

  update(dt) {
    this.particles.update(dt);
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const effect = this.effects[i];
      effect.life -= dt;
      const t = 1 - Math.max(0, effect.life) / effect.maxLife;
      effect.update?.(t, dt);
      if (effect.life <= 0) {
        effect.dispose?.();
        this.effects.splice(i, 1);
      }
    }
    this.updateNumbers(dt);
  }

  addEffect(effect) {
    this.effects.push(effect);
    return effect;
  }

  spark(position, element = 'physical', opts = {}) {
    this.particles.spawn(position, ELEMENT_COLORS[element] || element, {
      count: opts.count ?? 14,
      speed: opts.speed ?? 4.4,
      size: opts.size ?? 0.28,
      life: opts.life ?? 0.55,
      gravity: opts.gravity ?? 6,
      up: opts.up ?? 1.1,
      spread: 1.3,
      radius: opts.radius ?? 0.1,
    });
  }

  hit(position, element = 'physical', crit = false) {
    this.spark(position, element, { count: crit ? 24 : 15, speed: crit ? 6 : 4.6, size: 0.3 });
    this.spark(position, '#ffffff', { count: 5, speed: 3, size: 0.16, life: 0.3, gravity: 2 });
  }

  pickup(position, color = '#f3d998') {
    this.particles.spawn(position, color, {
      count: 12,
      speed: 2.2,
      size: 0.26,
      life: 0.9,
      gravity: -1.6,
      up: 1.4,
      radius: 0.25,
    });
  }

  heal(position) {
    this.particles.spawn(position, '#9cf5b3', {
      count: 20,
      speed: 1.6,
      size: 0.3,
      life: 1.4,
      gravity: -2,
      up: 1.8,
      radius: 0.7,
    });
  }

  burst(position, element, count = 70) {
    const color = ELEMENT_COLORS[element] || element;
    this.particles.spawn(position, color, {
      count,
      speed: 9,
      size: 0.42,
      life: 1.1,
      gravity: 2.5,
      up: 0.5,
      radius: 0.5,
    });
    this.particles.spawn(position, '#ffffff', {
      count: Math.floor(count * 0.25),
      speed: 12,
      size: 0.2,
      life: 0.6,
      gravity: 1,
      up: 0.4,
      radius: 0.3,
    });
  }

  slash(position, yaw, color) {
    const group = new THREE.Group();
    const mat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.85,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    const geo = new THREE.RingGeometry(1.0, 2.05, 32, 1, -0.5, 1.85);
    const arc = new THREE.Mesh(geo, mat);
    arc.rotation.z = 0.4;
    group.add(arc);
    const geo2 = new THREE.RingGeometry(0.8, 1.15, 24, 1, -0.3, 1.5);
    const arc2 = new THREE.Mesh(geo2, mat.clone());
    arc2.material.opacity = 0.5;
    arc2.rotation.z = 0.7;
    group.add(arc2);
    group.position.set(position.x, position.y + 1.15, position.z);
    group.rotation.y = yaw;
    group.scale.setScalar(0.75);
    this.scene.add(group);
    const forward = new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));
    group.position.addScaledVector(forward, 0.4);

    const effect = {
      life: 0.26,
      maxLife: 0.26,
      update: (t) => {
        group.scale.setScalar(0.78 + t * 0.55);
        group.position.y += 0.35 * (1 - t);
        mat.opacity = 0.9 * (1 - t);
        arc2.material.opacity = 0.55 * (1 - t);
        group.rotation.z = -0.7 * t;
      },
      dispose: () => {
        this.scene.remove(group);
        geo.dispose();
        geo2.dispose();
        mat.dispose();
        arc2.material.dispose();
      },
    };
    this.addEffect(effect);
  }

  shockwave(position, color, radius = 5, opts = {}) {
    const plane = new THREE.Mesh(
      new THREE.RingGeometry(0.5, 0.66, 48),
      new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.8,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      })
    );
    plane.rotation.x = -Math.PI / 2;
    plane.position.set(position.x, position.y + (opts.height ?? 0.12), position.z);
    this.scene.add(plane);
    const maxLife = opts.life ?? 0.65;
    const effect = {
      life: maxLife,
      maxLife,
      update: (t) => {
        const s = 1 + t * radius;
        plane.scale.setScalar(s);
        plane.material.opacity = 0.85 * (1 - t) ** 1.4;
      },
      dispose: () => {
        this.scene.remove(plane);
        plane.geometry.dispose();
        plane.material.dispose();
      },
    };
    this.addEffect(effect);
  }

  explosion(position, element, radius = 3.2) {
    const color = ELEMENT_COLORS[element] || element;
    this.shockwave(position, color, radius * 2.1, { life: 0.5 });
    this.particles.spawn(position, color, {
      count: 38,
      speed: radius * 2.4,
      size: 0.38,
      life: 0.85,
      gravity: 4,
      up: 0.7,
      radius: 0.35,
    });
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.6, 16, 12),
      new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.7,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      })
    );
    sphere.position.copy(position).add(new THREE.Vector3(0, 0.8, 0));
    this.scene.add(sphere);
    const maxLife = 0.5;
    this.addEffect({
      life: maxLife,
      maxLife,
      update: (t) => {
        sphere.scale.setScalar(1 + t * radius * 1.4);
        sphere.material.opacity = 0.6 * (1 - t) ** 1.5;
      },
      dispose: () => {
        this.scene.remove(sphere);
        sphere.geometry.dispose();
        sphere.material.dispose();
      },
    });
  }

  vortex(position, element = 'anemo', duration = 1.6) {
    const color = ELEMENT_COLORS[element] || element;
    const group = new THREE.Group();
    group.position.copy(position);
    group.position.y += 0.9;
    const rings = [];
    for (let i = 0; i < 3; i++) {
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(0.7 + i * 0.35, 0.035, 5, 40),
        new THREE.MeshBasicMaterial({
          color,
          transparent: true,
          opacity: 0.55 - i * 0.1,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        })
      );
      ring.rotation.x = Math.PI / 2 + i * 0.25;
      ring.rotation.z = i * 0.4;
      group.add(ring);
      rings.push(ring);
    }
    const glow = glowSprite(color, 4, 0.5);
    group.add(glow);
    this.scene.add(group);

    const effect = {
      life: duration,
      maxLife: duration,
      update: (t, dt) => {
        group.rotation.y += dt * 5.5;
        rings.forEach((ring, i) => {
          ring.rotation.z += dt * (2.6 + i);
          ring.scale.setScalar(1 + Math.sin(t * 8 + i) * 0.12);
          ring.material.opacity = (0.5 - i * 0.09) * (1 - t * 0.45);
        });
        group.position.y += Math.sin(t * Math.PI) * dt * 0.5;
        if (Math.random() < dt * 40) {
          const a = Math.random() * Math.PI * 2;
          const r = 0.6 + Math.random() * 1.8;
          this.particles.spawn(
            new THREE.Vector3(
              position.x + Math.cos(a) * r,
              position.y + Math.random() * 1.5,
              position.z + Math.sin(a) * r
            ),
            color,
            { count: 1, speed: 1.2, size: 0.22, life: 0.8, gravity: -1.8, up: 2.2, radius: 0 }
          );
        }
      },
      dispose: () => {
        this.scene.remove(group);
        rings.forEach((r) => {
          r.geometry.dispose();
          r.material.dispose();
        });
        glow.material.dispose();
      },
    };
    return this.addEffect(effect);
  }

  pillar(position, color, height = 8, duration = 1.1) {
    const mesh = new THREE.Mesh(
      new THREE.CylinderGeometry(1.6, 2.1, height, 24, 1, true),
      new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.35,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      })
    );
    mesh.position.set(position.x, position.y + height / 2, position.z);
    this.scene.add(mesh);
    const effect = {
      life: duration,
      maxLife: duration,
      update: (t) => {
        mesh.scale.set(1 + t * 0.5, 1, 1 + t * 0.5);
        mesh.material.opacity = 0.38 * (1 - t) ** 1.3;
      },
      dispose: () => {
        this.scene.remove(mesh);
        mesh.geometry.dispose();
        mesh.material.dispose();
      },
    };
    return this.addEffect(effect);
  }

  meteor(from, to, color, duration, onImpact) {
    const ball = new THREE.Mesh(
      new THREE.IcosahedronGeometry(0.42, 1),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 })
    );
    ball.add(glowSprite(color, 2.6, 0.9));
    ball.position.copy(from);
    this.scene.add(ball);
    const effect = {
      life: duration,
      maxLife: duration,
      update: (t) => {
        const eased = t * t;
        ball.position.lerpVectors(from, to, eased);
        if (Math.random() < 0.8) {
          this.particles.spawn(ball.position, color, {
            count: 1,
            speed: 0.6,
            size: 0.3,
            life: 0.5,
            gravity: -0.4,
            up: 0.3,
            radius: 0.1,
          });
        }
      },
      dispose: () => {
        this.scene.remove(ball);
        ball.geometry.dispose();
        ball.material.dispose();
        onImpact?.(to);
      },
    };
    return this.addEffect(effect);
  }

  floatText(position, text, opts = {}) {
    const el = document.createElement('div');
    el.className = `dmg${opts.kind ? ` ${opts.kind}` : ''}`;
    el.textContent = text;
    this.damageLayer.appendChild(el);
    this.numbers.push({
      el,
      position: position.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.5, 1 + Math.random() * 0.4, (Math.random() - 0.5) * 0.5)),
      life: 0.95,
      maxLife: 0.95,
      drift: (Math.random() - 0.5) * 20,
    });
  }

  updateNumbers(dt) {
    const w = window.innerWidth;
    const h = window.innerHeight;
    for (let i = this.numbers.length - 1; i >= 0; i--) {
      const item = this.numbers[i];
      item.life -= dt;
      if (item.life <= 0) {
        item.el.remove();
        this.numbers.splice(i, 1);
        continue;
      }
      this.projectile.copy(item.position).project(this.camera);
      if (this.projectile.z > 1) {
        item.el.style.display = 'none';
        continue;
      }
      item.el.style.display = '';
      const x = (this.projectile.x * 0.5 + 0.5) * w;
      const y = (-this.projectile.y * 0.5 + 0.5) * h;
      item.el.style.left = `${x + item.drift * (1 - item.life / item.maxLife)}px`;
      item.el.style.top = `${y}px`;
    }
  }

  clearNumbers() {
    for (const n of this.numbers) n.el.remove();
    this.numbers.length = 0;
  }
}

import { clamp } from './look.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.ambientStarted = false;
    this.noiseBuffer = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) {
      this.enabled = false;
      return;
    }
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.3;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.createNoise(2.5);
    this.startAmbient();
  }

  createNoise(seconds) {
    const rate = this.ctx.sampleRate;
    const buffer = this.ctx.createBuffer(1, Math.floor(rate * seconds), rate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < data.length; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.96 + white * 0.04;
      data[i] = last * 2.6;
    }
    return buffer;
  }

  startAmbient() {
    if (this.ambientStarted || !this.ctx) return;
    this.ambientStarted = true;
    const ctx = this.ctx;

    const pad = ctx.createGain();
    pad.gain.value = 0.045;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 900;
    filter.Q.value = 0.8;
    pad.connect(filter);
    filter.connect(this.master);

    for (const [freq, detune, gain] of [
      [110, -6, 0.55],
      [164.81, 4, 0.32],
      [220, 8, 0.16],
    ]) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq;
      osc.detune.value = detune;
      const g = ctx.createGain();
      g.gain.value = gain;
      osc.connect(g);
      g.connect(pad);
      osc.start();
    }

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 280;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start();

    const wind = ctx.createBufferSource();
    wind.buffer = this.noiseBuffer;
    wind.loop = true;
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'bandpass';
    windFilter.frequency.value = 620;
    windFilter.Q.value = 0.35;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.11;
    wind.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(this.master);
    wind.start();

    const swell = ctx.createOscillator();
    swell.frequency.value = 0.055;
    const swellGain = ctx.createGain();
    swellGain.gain.value = 0.05;
    swell.connect(swellGain);
    swellGain.connect(windGain.gain);
    swell.start();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) this.master.gain.setTargetAtTime(on ? 0.3 : 0, this.ctx.currentTime, 0.08);
  }

  beep(freq, dur = 0.14, type = 'sine', gain = 0.18, slide = null, delay = 0) {
    if (!this.enabled || !this.ctx) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.03);
  }

  noise(dur = 0.2, freq = 900, gain = 0.12, delay = 0) {
    if (!this.enabled || !this.ctx) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(freq, t0);
    filter.frequency.exponentialRampToValueAtTime(Math.max(60, freq * 0.25), t0 + dur);
    filter.Q.value = 0.9;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  chord(freqs, dur = 0.5, type = 'sine', gain = 0.09) {
    freqs.forEach((f, i) => this.beep(f, dur, type, gain, f * 1.01, i * 0.025));
  }

  sfx(name) {
    if (!this.enabled || !this.ctx) return;
    switch (name) {
      case 'jump':
        this.beep(300, 0.18, 'sine', 0.1, 620);
        break;
      case 'land':
        this.noise(0.14, 220, 0.1);
        this.beep(90, 0.1, 'sine', 0.08, 60);
        break;
      case 'slash':
        this.noise(0.12, 2600, 0.13);
        this.beep(720, 0.07, 'triangle', 0.05, 360);
        break;
      case 'hit':
        this.noise(0.1, 1400, 0.1);
        this.beep(170, 0.1, 'square', 0.05, 90);
        break;
      case 'crit':
        this.noise(0.14, 2200, 0.14);
        this.beep(1040, 0.16, 'triangle', 0.08, 1560);
        break;
      case 'skillAnemo':
        this.noise(0.5, 800, 0.12);
        this.chord([523.25, 659.25, 783.99, 1046.5], 0.65, 'sine', 0.05);
        break;
      case 'skillPyro':
        this.noise(0.45, 500, 0.16);
        this.beep(120, 0.4, 'sawtooth', 0.07, 60);
        this.beep(392, 0.35, 'triangle', 0.06, 523);
        break;
      case 'burst':
        this.noise(0.8, 600, 0.16);
        this.chord([261.63, 329.63, 392, 523.25, 659.25], 1.1, 'triangle', 0.06);
        break;
      case 'pickup':
        [880, 1174.66, 1567.98].forEach((f, i) => this.beep(f, 0.2, 'sine', 0.09, f * 1.02, i * 0.07));
        break;
      case 'heal':
        [392, 523.25, 659.25, 880].forEach((f, i) => this.beep(f, 0.5, 'sine', 0.05, f * 1.01, i * 0.08));
        break;
      case 'hurt':
        this.beep(140, 0.22, 'sawtooth', 0.1, 70);
        this.noise(0.16, 500, 0.1);
        break;
      case 'switch':
        this.beep(660, 0.1, 'triangle', 0.06, 990);
        this.beep(990, 0.14, 'sine', 0.05, 1320, 0.05);
        break;
      case 'chest':
        this.chord([523.25, 659.25, 783.99, 1046.5, 1318.5], 1.2, 'sine', 0.075);
        this.noise(0.5, 1800, 0.08);
        break;
      case 'quest':
        this.chord([659.25, 783.99, 1046.5], 0.8, 'triangle', 0.06);
        break;
      case 'dialogue':
        this.beep(520, 0.05, 'sine', 0.025);
        break;
      case 'ui':
        this.beep(600, 0.06, 'sine', 0.04, 720);
        break;
      case 'death':
        this.chord([220, 261.63, 329.63], 1.6, 'sine', 0.06);
        this.beep(110, 1.4, 'sawtooth', 0.04, 55);
        break;
      default:
        break;
    }
  }
}

import * as THREE from 'three';
import { toon, glowSprite, clamp } from './look.js';
import { ELEMENT_COLORS } from './fx.js';
import { heightAt, slopeAt, BOSS_POS } from './world.js';

const TYPES = {
  hydro: { body: '#3f9bc9', light: '#a5e8ff', glow: '#6fc9ff', name: 'Slime Hydro' },
  pyro: { body: '#cf5b36', light: '#ffb27a', glow: '#ff9a5c', name: 'Slime Pyro' },
  electro: { body: '#8765ca', light: '#d3bcff', glow: '#c69bff', name: 'Slime Electro' },
};

const SPAWNS = [
  [18, 4, 'hydro'],
  [-14, -6, 'electro'],
  [20, -14, 'pyro'],
  [34, 18, 'hydro'],
  [-38, 12, 'electro'],
  [6, -34, 'pyro'],
  [-8, 40, 'hydro'],
  [40, -8, 'electro'],
  [30, 38, 'pyro'],
];

const REACTIONS = {
  'hydro+pyro': { name: 'UAP', mult: 1.8 },
  'pyro+hydro': { name: 'UAP', mult: 1.8 },
  'anemo+pyro': { name: 'KOBAR', mult: 1.35 },
  'pyro+anemo': { name: 'KOBAR', mult: 1.35 },
  'anemo+hydro': { name: 'PUSARAN', mult: 1.3 },
  'hydro+anemo': { name: 'PUSARAN', mult: 1.3 },
  'hydro+electro': { name: 'KEJUT', mult: 1.5 },
  'electro+hydro': { name: 'KEJUT', mult: 1.5 },
  'pyro+electro': { name: 'LEDAKAN', mult: 1.6 },
  'electro+pyro': { name: 'LEDAKAN', mult: 1.6 },
  'anemo+electro': { name: 'PUSARAN', mult: 1.3 },
  'electro+anemo': { name: 'PUSARAN', mult: 1.3 },
};

function makeSlime(type, scale, boss = false) {
  const data = TYPES[type];
  const group = new THREE.Group();
  const bodyMat = toon(data.body);
  const body = new THREE.Mesh(new THREE.SphereGeometry(0.72, 18, 14), bodyMat);
  body.position.y = 0.6;
  body.scale.set(1, 0.82, 1);
  body.castShadow = true;
  group.add(body);

  const belly = new THREE.Mesh(new THREE.SphereGeometry(0.5, 12, 10), toon(data.light));
  belly.position.set(0, 0.5, 0.14);
  belly.scale.set(1, 0.7, 0.55);
  group.add(belly);

  const core = new THREE.Mesh(
    new THREE.IcosahedronGeometry(0.17, 0),
    new THREE.MeshBasicMaterial({ color: data.glow, transparent: true, opacity: 0.85 })
  );
  core.position.set(0, 0.58, 0.3);
  group.add(core);

  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.115, 10, 8), new THREE.MeshBasicMaterial({ color: '#f7fffd' }));
    eye.position.set(side * 0.23, 0.74, 0.6);
    eye.scale.set(0.85, 1.1, 0.6);
    group.add(eye);
    const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), new THREE.MeshBasicMaterial({ color: '#17262d' }));
    pupil.position.set(side * 0.23, 0.74, 0.685);
    pupil.scale.set(0.9, 1.3, 0.4);
    group.add(pupil);
    const brow = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.028, 0.02), new THREE.MeshBasicMaterial({ color: '#2a1e1e' }));
    brow.position.set(side * 0.23, 0.87, 0.66);
    brow.rotation.z = side * -0.28;
    group.add(brow);
  }

  const mouth = new THREE.Mesh(
    new THREE.BoxGeometry(0.2, 0.035, 0.02),
    new THREE.MeshBasicMaterial({ color: '#3b2323' })
  );
  mouth.position.set(0, 0.58, 0.67);
  group.add(mouth);

  const glow = glowSprite(data.glow, 2.2, 0.3);
  glow.position.y = 0.6;
  group.add(glow);

  if (boss) {
    const crown = new THREE.Group();
    const gold = toon('#f0cc76');
    for (let i = 0; i < 5; i++) {
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.34, 4), gold);
      const a = (i / 5) * Math.PI * 2;
      spike.position.set(Math.cos(a) * 0.34, 1.28, Math.sin(a) * 0.34);
      spike.rotation.z = -Math.cos(a) * 0.25;
      spike.rotation.x = Math.sin(a) * 0.25;
      crown.add(spike);
    }
    group.add(crown);
    const horn = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.5, 5), toon('#e8e1c8'));
    horn.position.set(0, 1.2, 0.32);
    horn.rotation.x = 0.35;
    group.add(horn);
  }

  group.scale.setScalar(scale);
  group.userData = { body, belly, core, glow, bodyMat, eyes: [] };
  return group;
}

export class EnemyManager {
  constructor({ scene, fx, audio, ui, camera, onKill }) {
    this.scene = scene;
    this.fx = fx;
    this.audio = audio;
    this.ui = ui;
    this.camera = camera;
    this.onKill = onKill;
    this.enemies = [];
    this.bars = [];
    this.boss = null;
    this.kills = 0;
    this.vortex = null;
    this.time = 0;
    this.barLayer = document.getElementById('enemy-bars');
    this.tmp = new THREE.Vector3();

    SPAWNS.forEach(([x, z, type]) => this.spawn(x, z, type, 1));
    this.boss = this.spawn(BOSS_POS.x, BOSS_POS.z, 'hydro', 2.15, true);
  }

  spawn(x, z, type, scale, boss = false) {
    const group = makeSlime(type, scale, boss);
    const y = heightAt(x, z);
    group.position.set(x, y, z);
    this.scene.add(group);

    const bar = document.createElement('div');
    bar.className = `enemy-bar${boss ? ' boss' : ''}`;
    bar.innerHTML = `<span class="eb-name">${boss ? 'Raja Slime Purba' : TYPES[type].name}</span><div class="eb-track"><div class="eb-fill"></div></div>`;
    this.barLayer.appendChild(bar);

    const enemy = {
      group,
      body,
      type,
      boss,
      home: new THREE.Vector3(x, y, z),
      pos: group.position,
      scale,
      hp: boss ? 420 : 72,
      maxHp: boss ? 420 : 72,
      radius: 0.72 * scale,
      state: 'idle',
      stateT: 0,
      attackCooldown: 1 + Math.random() * 2,
      wanderAngle: Math.random() * Math.PI * 2,
      wanderT: 0,
      aura: { element: type, until: Infinity },
      burning: null,
      flash: 0,
      dead: false,
      respawn: 0,
      velocity: new THREE.Vector3(),
      phase: Math.random() * 6.28,
      bar,
      fill: bar.querySelector('.eb-fill'),
      hitFlash: 0,
      lastHit: 0,
    };
    enemy.group.userData.enemy = enemy;
    this.enemies.push(enemy);
    return enemy;
  }

  get alive() {
    return this.enemies.filter((e) => !e.dead);
  }

  nearest(position, maxDistance = 999) {
    let best = null;
    let bestD = maxDistance;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = Math.hypot(e.pos.x - position.x, e.pos.z - position.z);
      if (d < bestD) {
        bestD = d;
        best = e;
      }
    }
    return best;
  }

  setVortex(center, radius, duration, dps, element = 'anemo') {
    this.vortex = { center: center.clone(), radius, until: this.time + duration, dps, element, tick: 0 };
  }

  update(dt, player, elapsed) {
    this.time = elapsed;
    const pAlive = player.alive;
    const px = player.pos.x;
    const pz = player.pos.z;
    const py = player.pos.y;

    if (this.vortex) {
      if (elapsed > this.vortex.until) this.vortex = null;
      else this.vortex.tick -= dt;
    }

    for (const e of this.enemies) {
      if (e.dead) {
        e.respawn -= dt;
        if (e.respawn <= 0) this.respawn(e, player);
        continue;
      }

      const dist = Math.hypot(e.pos.x - px, e.pos.z - pz);
      e.stateT += dt;
      e.attackCooldown -= dt;
      e.flash = Math.max(0, e.flash - dt * 4);
      e.hitFlash = Math.max(0, e.hitFlash - dt * 6);

      // Elemental aura slowly decays.
      if (e.aura.until !== Infinity && elapsed > e.aura.until) e.aura = { element: null, until: 0 };

      // Burning damage-over-time from a Kobar reaction.
      if (e.burning) {
        e.burning.t -= dt;
        e.burning.tick -= dt;
        if (e.burning.tick <= 0) {
          e.burning.tick = 0.62;
          this.rawDamage(e, 7 + player.level * 1.2, 'pyro', false, true);
          const pos = e.pos.clone();
          pos.y += 0.8 * e.scale;
          this.fx.spark(pos, 'pyro', { count: 5, speed: 1.6, size: 0.22, life: 0.5, gravity: -1, up: 1.6 });
        }
        if (e.burning.t <= 0) e.burning = null;
      }

      if (e.dead) continue;

      // Anemo vortex pulls enemies toward its centre.
      if (this.vortex) {
        const v = this.vortex;
        const dx = v.center.x - e.pos.x;
        const dz = v.center.z - e.pos.z;
        const vd = Math.hypot(dx, dz);
        if (vd < v.radius && vd > 0.2) {
          const pull = (1 - vd / v.radius) * 4.4;
          e.pos.x += (dx / vd) * pull * dt;
          e.pos.z += (dz / vd) * pull * dt;
          e.state = 'pulled';
          e.stateT = 0;
          if (Math.random() < dt * 6) {
            const p = e.pos.clone();
            p.y += 0.8;
            this.fx.spark(p, v.element, { count: 2, speed: 1, size: 0.18, life: 0.5, gravity: -1.5, up: 2 });
          }
          if (v.tick <= 0) {
            v.tick = 0.5;
            this.rawDamage(e, v.dps * 0.5, v.element, false, true);
          }
        }
      }

      // Hit knockback smoothing.
      e.pos.x += e.velocity.x * dt;
      e.pos.z += e.velocity.z * dt;
      e.velocity.multiplyScalar(Math.max(0, 1 - 8 * dt));

      const aggro = pAlive && dist < (e.boss ? 22 : 16);
      if (e.state === 'windup' || e.state === 'pulled') {
        // stay put while telegraphing / being pulled
      } else if (aggro) {
        const speed = e.boss ? 2.1 : 2.4;
        if (dist > (e.boss ? 3.6 : 2.5)) {
          const nx = (px - e.pos.x) / dist;
          const nz = (pz - e.pos.z) / dist;
          const wobble = Math.sin(elapsed * 4 + e.phase) * 0.32;
          const targetX = e.pos.x + (nx + -nz * wobble) * speed * dt;
          const targetZ = e.pos.z + (nz + nx * wobble) * speed * dt;
          const h = heightAt(targetX, targetZ);
          if (h > -0.4) {
            e.pos.x = targetX;
            e.pos.z = targetZ;
          }
          e.state = 'chase';
        } else {
          e.state = 'chase';
          if (e.attackCooldown <= 0) {
            e.state = 'windup';
            e.stateT = 0;
            e.attackCooldown = e.boss ? 2.6 : 2.2;
          }
        }
      } else {
        // gentle wander around the spawn point
        e.wanderT -= dt;
        if (e.wanderT <= 0) {
          e.wanderT = 2.4 + Math.random() * 3.5;
          e.wanderAngle = Math.random() * Math.PI * 2;
        }
        if (e.state === 'chase') e.state = 'idle';
        const homeDist = Math.hypot(e.pos.x - e.home.x, e.pos.z - e.home.z);
        if (homeDist < 5) {
          const nx = e.pos.x + Math.cos(e.wanderAngle) * 0.55 * dt;
          const nz = e.pos.z + Math.sin(e.wanderAngle) * 0.55 * dt;
          if (heightAt(nx, nz) > -0.2) {
            e.pos.x = nx;
            e.pos.z = nz;
          }
        } else {
          const nx = (e.home.x - e.pos.x) / homeDist;
          const nz = (e.home.z - e.pos.z) / homeDist;
          e.pos.x += nx * 0.9 * dt;
          e.pos.z += nz * 0.9 * dt;
        }
      }

      // Windup then strike.
      if (e.state === 'windup' && e.stateT > (e.boss ? 0.62 : 0.48)) {
        const strikeDist = Math.hypot(px - e.pos.x, pz - e.pos.z);
        if (pAlive && strikeDist < 3.2 * (e.boss ? 1.25 : 1)) {
          const dmg = e.boss ? 20 : 11;
          player.takeDamage(dmg, e.pos, e.type);
          if (e.boss) {
            this.fx.shockwave(e.pos.clone(), ELEMENT_COLORS.hydro, 3.4, { life: 0.4 });
          }
        }
        this.fx.spark(
          new THREE.Vector3(e.pos.x, e.pos.y + 0.5, e.pos.z),
          e.type,
          { count: 12, speed: 3.5, size: 0.25, life: 0.5, gravity: 6, up: 0.5 }
        );
        this.audio.sfx('land');
        e.state = 'idle';
        e.stateT = 0;
      }

      // Keep slimes planted on the terrain and face the player.
      const ground = heightAt(e.pos.x, e.pos.z);
      e.pos.y = ground + 0.02;
      if (aggro || e.state === 'windup') {
        const targetYaw = Math.atan2(px - e.pos.x, pz - e.pos.z);
        let diff = targetYaw - e.group.rotation.y;
        diff = Math.atan2(Math.sin(diff), Math.cos(diff));
        e.group.rotation.y += diff * Math.min(1, dt * 7);
      } else {
        e.group.rotation.y += dt * 0.4;
      }

      // Squash/stretch + element flash.
      const squash = e.state === 'windup' ? 0.78 + Math.sin(elapsed * 30) * 0.05 : 1 + Math.sin(elapsed * 4.2 + e.phase) * 0.06;
      e.group.userData.body.scale.set(1.04 / Math.sqrt(squash), 0.82 * squash, 1.04 / Math.sqrt(squash));
      const flash = Math.max(e.flash, e.hitFlash * 0.55);
      e.group.userData.bodyMat.emissive.setRGB(flash, flash, flash);
      e.group.userData.bodyMat.emissiveIntensity = flash * 1.4;

      // Update floating HP bar.
      this.updateBar(e, dist);
    }

    // Hide bars for enemies that are far away.
    for (const e of this.enemies) {
      if (e.dead) e.bar.style.display = 'none';
    }
  }

  updateBar(e, dist) {
    const bar = e.bar;
    const scale = e.scale;
    this.tmp.set(e.pos.x, e.pos.y + 1.7 * scale + 0.5, e.pos.z);
    this.tmp.project(this.camera);
    const visible = dist < (e.boss ? 34 : 26) && this.tmp.z < 1 && this.tmp.z > -1;
    if (!visible) {
      bar.style.display = 'none';
      return;
    }
    bar.style.display = '';
    bar.style.left = `${(this.tmp.x * 0.5 + 0.5) * window.innerWidth}px`;
    bar.style.top = `${(-this.tmp.y * 0.5 + 0.5) * window.innerHeight}px`;
    bar.style.opacity = clamp(1.4 - dist / 34, 0.25, 1);
    e.fill.style.width = `${Math.max(0, (e.hp / e.maxHp) * 100)}%`;
  }

  hitCone(origin, direction, range, cosHalf, damage, element, crit) {
    const hits = [];
    for (const e of this.enemies) {
      if (e.dead) continue;
      const dx = e.pos.x - origin.x;
      const dz = e.pos.z - origin.z;
      const d = Math.hypot(dx, dz);
      if (d > range + e.radius) continue;
      const dot = (dx / (d || 1)) * direction.x + (dz / (d || 1)) * direction.z;
      if (dot < cosHalf && d > 1.2) continue;
      hits.push(e);
      this.applyDamage(e, damage, element, { crit, from: origin, knockback: 2.6 });
    }
    return hits;
  }

  damageArea(center, radius, damage, element, { crit = false, knockback = 1.4 } = {}) {
    const hits = [];
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = Math.hypot(e.pos.x - center.x, e.pos.z - center.z);
      if (d > radius + e.radius) continue;
      hits.push(e);
      const falloff = 1 - clamp((d - radius * 0.4) / (radius * 0.8), 0, 0.45);
      this.applyDamage(e, damage * falloff, element, { crit, from: center, knockback });
    }
    return hits;
  }

  applyDamage(enemy, baseDamage, element, { crit = false, from = null, knockback = 1.2, silent = false } = {}) {
    if (enemy.dead) return 0;

    // Elemental reaction with the aura currently on the target.
    let multiplier = 1;
    let reaction = null;
    const auraEl = enemy.aura?.element;
    if (auraEl && auraEl !== element) {
      const key = `${auraEl}+${element}`;
      if (REACTIONS[key]) {
        reaction = REACTIONS[key];
        multiplier = reaction.mult;
        enemy.aura = { element: null, until: 0 };
        if (reaction.name === 'KOBAR') {
          enemy.burning = { t: 3.2, tick: 0, name: 'Kobar' };
        } else if (reaction.name === 'KEJUT') {
          // Electro-charged arcs to one nearby enemy.
          const other = this.enemies.find(
            (o) => o !== enemy && !o.dead && Math.hypot(o.pos.x - enemy.pos.x, o.pos.z - enemy.pos.z) < 7
          );
          if (other) setTimeout(() => this.rawDamage(other, baseDamage * 0.45, 'electro', false, false), 120);
        }
      }
    }
    if (element !== 'physical' && element !== 'anemo') {
      if (!enemy.burning) enemy.aura = { element, until: this.time + 7 };
    } else if (element === 'anemo' && !auraEl) {
      enemy.aura = { element: null, until: 0 };
    }

    if (reaction) {
      this.ui?.showReaction(reaction.name);
      const p = enemy.pos.clone();
      p.y += 1.1;
      this.fx.floatText(p, reaction.name, { kind: 'reaction' });
      this.fx.burst(enemy.pos.clone().add(new THREE.Vector3(0, 0.7, 0)), element, 26);
    }

    const variance = 0.92 + Math.random() * 0.16;
    const amount = baseDamage * multiplier * variance * (crit ? 1.9 : 1);
    const dealt = this.rawDamage(enemy, amount, element, crit, silent);
    enemy.flash = 1;

    if (from) {
      const dx = enemy.pos.x - from.x;
      const dz = enemy.pos.z - from.z;
      const d = Math.hypot(dx, dz) || 1;
      enemy.velocity.x += (dx / d) * knockback;
      enemy.velocity.z += (dz / d) * knockback;
    }
    return dealt;
  }

  rawDamage(enemy, amount, element, crit = false, silent = false) {
    if (enemy.dead) return 0;
    const dmg = Math.max(1, Math.round(amount));
    enemy.hp -= dmg;
    const p = enemy.pos.clone();
    p.y += 0.95 * enemy.scale + Math.random() * 0.4;
    if (!silent) {
      this.fx.floatText(p, String(dmg), { kind: crit ? 'crit' : '' });
      this.fx.hit(p, element, crit);
      this.audio.sfx(crit ? 'crit' : 'hit');
    }
    if (enemy.hp <= 0) this.kill(enemy);
    return dmg;
  }

  kill(enemy) {
    if (enemy.dead) return;
    enemy.dead = true;
    enemy.hp = 0;
    enemy.respawn = enemy.boss ? 55 : 30;
    enemy.bar.style.display = 'none';
    enemy.group.visible = false;
    enemy.aura = { element: null, until: 0 };
    enemy.burning = null;

    const pos = enemy.pos.clone();
    pos.y += 0.6;
    this.fx.burst(pos, enemy.type, enemy.boss ? 120 : 48);
    this.fx.shockwave(pos, ELEMENT_COLORS[enemy.type], enemy.boss ? 8 : 2.5, { life: 0.55 });
    this.fx.pickup(pos, '#ffe29a');
    this.audio.sfx('burst');
    this.kills++;
    this.onKill?.(enemy);
    if (enemy.boss) this.ui?.toast('Raja Slime Purba tumbang!', '✦');
  }

  respawn(enemy, player) {
    const dist = Math.hypot(player.pos.x - enemy.home.x, player.pos.z - enemy.home.z);
    if (dist < 22) {
      enemy.respawn = 4;
      return;
    }
    enemy.dead = false;
    enemy.hp = enemy.maxHp;
    enemy.group.visible = true;
    enemy.group.position.copy(enemy.home);
    enemy.state = 'idle';
    enemy.aura = { element: enemy.type, until: Infinity };
    enemy.scale = enemy.scale;
    this.fx.pickup(enemy.pos.clone().add(new THREE.Vector3(0, 1, 0)), ELEMENT_COLORS[enemy.type]);
  }

  get bossBarData() {
    if (!this.boss || this.boss.dead) return null;
    return this.boss;
  }
}

import * as THREE from 'three';
import { createCharacter, CHARACTERS } from './character.js';
import { clamp, damp } from './look.js';
import { ELEMENT_COLORS } from './fx.js';
import {
  heightAt,
  slopeAt,
  WATER_Y,
  WORLD_RADIUS,
  SPAWN,
  STATUE_POS,
} from './world.js';

const GRAVITY = 27;
const MAX_ENERGY = 80;

function angleLerp(a, b, t) {
  let d = b - a;
  d = Math.atan2(Math.sin(d), Math.cos(d));
  return a + d * t;
}

export class Player {
  constructor({ scene, camera, world, fx, enemies, audio, ui }) {
    this.scene = scene;
    this.camera = camera;
    this.world = world;
    this.fx = fx;
    this.enemies = enemies;
    this.audio = audio;
    this.ui = ui;

    this.level = 12;
    this.maxHealth = 100;
    this.health = 100;
    this.maxStamina = 100;
    this.stamina = 100;
    this.energy = [42, 46];
    this.cooldowns = [0, 0];
    this.maxEnergy = MAX_ENERGY;

    this.pos = new THREE.Vector3(SPAWN.x, heightAt(SPAWN.x, SPAWN.z), SPAWN.z);
    this.vel = new THREE.Vector3();
    this.facing = Math.PI;
    this.active = 0;
    this.alive = true;
    this.onGround = true;
    this.gliding = false;
    this.swimming = false;
    this.sprinting = false;
    this.invuln = 0;
    this.airTime = 0;
    this.staminaDelay = 0;
    this.lastDamageAt = -99;
    this.stepTimer = 0;
    this.healFxTimer = 0;
    this.nearStatue = false;
    this.shake = 0;
    this.flash = 0;
    this.pendingMeteors = [];
    this.statsDirty = true;

    this.attackTime = -1;
    this.attackDuration = 0.46;
    this.attackHit = false;
    this.attackQueued = false;
    this.combo = 0;
    this.castTime = 0;
    this.castDuration = 0;

    this.characters = CHARACTERS.map((_, i) => {
      const character = createCharacter(i);
      character.setVisible(i === 0);
      this.scene.add(character.root);
      return character;
    });
    this.characters[0].root.position.copy(this.pos);
    this.characters[0].root.rotation.y = this.facing;

    this.tmp = new THREE.Vector3();
    this.moveDir = new THREE.Vector3();
    this.forwardVec = new THREE.Vector3();
    this.lookVec = new THREE.Vector3();
  }

  get character() {
    return this.characters[this.active];
  }

  get data() {
    return CHARACTERS[this.active];
  }

  get forward() {
    return this.forwardVec.set(Math.sin(this.facing), 0, Math.cos(this.facing));
  }

  get energyReady() {
    return this.energy[this.active] >= MAX_ENERGY;
  }

  switchTo(index) {
    if (!this.alive || index === this.active || index < 0 || index > 1) return;
    this.characters[this.active].setVisible(false);
    this.active = index;
    const next = this.characters[index];
    next.setVisible(true);
    next.root.position.copy(this.pos);
    next.root.rotation.y = this.facing;
    this.attackTime = -1;
    this.castTime = 0;
    this.invuln = Math.max(this.invuln, 0.5);
    this.fx.burst(this.pos.clone().add(new THREE.Vector3(0, 1.1, 0)), this.data.element, 26);
    this.fx.shockwave(this.pos, ELEMENT_COLORS[this.data.element], 2.4, { life: 0.45 });
    this.audio.sfx('switch');
    this.ui.toast(`<b>${this.data.name}</b> · ${this.data.elementLabel}`, '❖');
    this.ui.setElement(this.data.element);
    this.ui.updateParty(this);
    this.statsDirty = true;
  }

  tryAttack() {
    if (!this.alive) return;
    if (this.attackTime >= 0 && this.attackTime < this.attackDuration - 0.08) {
      this.attackQueued = true;
      return;
    }
    this.startAttack();
  }

  startAttack() {
    const target = this.autoTarget(7);
    if (target) {
      this.facing = angleLerp(this.facing, Math.atan2(target.pos.x - this.pos.x, target.pos.z - this.pos.z), 1);
      this.character.root.rotation.y = this.facing;
    } else {
      this.facing = Math.atan2(-Math.sin(this.camera.userData.yaw), -Math.cos(this.camera.userData.yaw));
    }
    this.combo = (this.combo + 1) % 3;
    this.attackTime = 0;
    this.attackDuration = this.combo === 2 ? 0.54 : 0.4;
    this.attackHit = false;
    this.attackQueued = false;
    this.audio.sfx('slash');
    const f = this.forward;
    const slashPos = this.pos.clone().addScaledVector(f, 0.2);
    this.fx.slash(slashPos, this.facing, ELEMENT_COLORS[this.data.element]);
  }

  autoTarget(range) {
    const enemy = this.enemies.nearest(this.pos, range);
    if (!enemy) return null;
    const dx = enemy.pos.x - this.pos.x;
    const dz = enemy.pos.z - this.pos.z;
    const d = Math.hypot(dx, dz) || 1;
    const f = this.forward;
    const dot = (dx / d) * f.x + (dz / d) * f.z;
    return dot > -0.1 ? enemy : null;
  }

  applyAttackHit() {
    const comboDamage = [17, 19, 30][this.combo];
    const crit = Math.random() < 0.22;
    const f = this.forward;
    const hits = this.enemies.hitCone(
      this.pos,
      f,
      3.15,
      Math.cos((64 * Math.PI) / 180),
      comboDamage * (1 + (this.level - 1) * 0.018),
      this.data.element,
      crit
    );
    if (hits.length) {
      this.energy[this.active] = Math.min(MAX_ENERGY, this.energy[this.active] + 5);
      this.shake = Math.max(this.shake, crit ? 0.32 : 0.16);
      this.statsDirty = true;
    } else {
      this.audio.sfx('slash');
    }
    this.lookVec.copy(f).multiplyScalar(0.5);
    this.pos.add(this.lookVec);
  }

  useSkill() {
    if (!this.alive || this.cooldowns[this.active] > 0) return;
    const char = this.data;
    const f = this.forward;
    const target = this.autoTarget(9);
    if (target) {
      this.facing = Math.atan2(target.pos.x - this.pos.x, target.pos.z - this.pos.z);
    }

    if (char.element === 'anemo') {
      const center = this.pos.clone().addScaledVector(this.forward, 5.6);
      const gy = heightAt(center.x, center.z);
      center.y = Math.max(gy, WATER_Y);
      this.enemies.setVortex(center, 6.2, 1.8, 26, 'anemo');
      this.enemies.damageArea(center, 2.2, 22 * (1 + this.level * 0.01), 'anemo', { knockback: 0.4 });
      this.fx.vortex(center, 'anemo', 1.9);
      this.fx.shockwave(center, ELEMENT_COLORS.anemo, 5.2, { life: 0.7, height: 0.2 });
      this.audio.sfx('skillAnemo');
      this.cooldowns[this.active] = 7;
    } else {
      const center = this.pos.clone().addScaledVector(f, 1.8);
      this.enemies.damageArea(center, 4.6, 52 * (1 + this.level * 0.012), 'pyro', { knockback: 3.2 });
      this.enemies.enemies.forEach((e) => {
        if (!e.dead && Math.hypot(e.pos.x - center.x, e.pos.z - center.z) < 4.6) {
          e.burning = { t: 4, tick: 0 };
        }
      });
      this.fx.explosion(center, 'pyro', 4.4);
      this.fx.shockwave(center, ELEMENT_COLORS.pyro, 6.5, { life: 0.55 });
      this.audio.sfx('skillPyro');
      this.shake = 0.5;
      this.cooldowns[this.active] = 6;
    }

    this.energy[this.active] = Math.min(MAX_ENERGY, this.energy[this.active] + 11);
    this.castTime = 0.62;
    this.castDuration = 0.62;
    this.character.anim.cast = 0;
    this.statsDirty = true;
  }

  useBurst() {
    if (!this.alive) return;
    if (this.energy[this.active] < MAX_ENERGY) {
      this.ui.toast(`Energi belum cukup · ${Math.floor(this.energy[this.active])}/${MAX_ENERGY}`, '✦');
      this.audio.sfx('ui');
      return;
    }
    const char = this.data;
    this.energy[this.active] = 0;
    this.invuln = Math.max(this.invuln, 1.2);
    this.shake = 0.85;
    this.flash = 0.6;
    this.ui.flashScreen();
    this.audio.sfx('burst');
    this.character.anim.cast = 0;
    this.castTime = 0.9;
    this.castDuration = 0.9;

    if (char.element === 'anemo') {
      const center = this.pos.clone();
      this.enemies.damageArea(center, 8.5, 105 * (1 + this.level * 0.015), 'anemo', { knockback: 6 });
      this.enemies.setVortex(center, 8, 2.1, 34, 'anemo');
      this.fx.burst(center.clone().add(new THREE.Vector3(0, 0.8, 0)), 'anemo', 110);
      this.fx.shockwave(center, ELEMENT_COLORS.anemo, 9, { life: 0.9 });
      this.fx.pillar(center, ELEMENT_COLORS.anemo, 10, 1.3);
      this.fx.vortex(center, 'anemo', 2.1);
      this.ui.showReaction('BADAI ZEPHYR');
    } else {
      const center = this.pos.clone();
      this.enemies.damageArea(center, 5.5, 70 * (1 + this.level * 0.015), 'pyro', { knockback: 5 });
      this.fx.burst(center.clone().add(new THREE.Vector3(0, 1, 0)), 'pyro', 100);
      this.fx.shockwave(center, ELEMENT_COLORS.pyro, 7, { life: 0.8 });
      this.fx.pillar(center, ELEMENT_COLORS.pyro, 8, 1.1);
      for (let i = 0; i < 6; i++) {
        this.pendingMeteors.push({
          delay: 0.15 + i * 0.12,
          offset: new THREE.Vector3((Math.random() - 0.5) * 9, 0, (Math.random() - 0.5) * 9),
        });
      }
      this.ui.showReaction('HUJAN METEOR');
    }
    this.statsDirty = true;
    this.ui.updateParty(this);
  }

  spawnMeteor(offset) {
    const to = this.pos.clone().add(offset);
    to.y = heightAt(to.x, to.z) + 0.2;
    const from = to.clone().add(new THREE.Vector3(2, 16, 1.5));
    this.fx.meteor(from, to, ELEMENT_COLORS.pyro, 0.55, (impact) => {
      if (!this.alive) return;
      this.enemies.damageArea(impact, 3.1, 46 * (1 + this.level * 0.012), 'pyro', { knockback: 3.4 });
      this.fx.explosion(impact, 'pyro', 3.1);
      this.audio.sfx('hit');
      this.shake = Math.max(this.shake, 0.25);
    });
  }

  takeDamage(amount, source, element = 'physical') {
    if (!this.alive || this.invuln > 0) return;
    this.health = Math.max(0, this.health - amount);
    this.invuln = 0.85;
    this.lastDamageAt = this.world ? performance.now() / 1000 : 0;
    this.character.anim.hurt = 1;
    this.shake = 0.55;
    this.fx.floatText(this.pos.clone().add(new THREE.Vector3(0, 1.6, 0)), `-${Math.round(amount)}`, { kind: 'heal' });
    this.fx.spark(this.pos.clone().add(new THREE.Vector3(0, 1, 0)), 'pyro', { count: 12, speed: 3, size: 0.25 });
    this.audio.sfx('hurt');
    this.ui.damageFlash();
    if (source) {
      const dx = this.pos.x - source.x;
      const dz = this.pos.z - source.z;
      const d = Math.hypot(dx, dz) || 1;
      this.vel.x += (dx / d) * 5;
      this.vel.z += (dz / d) * 5;
      this.vel.y = Math.max(this.vel.y, 2.4);
      this.onGround = false;
    }
    if (this.health <= 0) this.die();
    this.statsDirty = true;
  }

  heal(amount, { silent = false, fx = false } = {}) {
    if (!this.alive) return;
    const before = this.health;
    this.health = Math.min(this.maxHealth, this.health + amount);
    const gained = this.health - before;
    if (gained > 0.5 && !silent) {
      this.statsDirty = true;
      if (fx) {
        this.fx.heal(this.pos.clone().add(new THREE.Vector3(0, 1, 0)));
        this.fx.floatText(this.pos.clone().add(new THREE.Vector3(0, 1.7, 0)), `+${Math.round(gained)}`, { kind: 'heal' });
      }
    }
  }

  die() {
    this.alive = false;
    this.gliding = false;
    this.audio.sfx('death');
    this.character.setVisible(false);
    this.ui.showDeath();
  }

  respawn() {
    this.alive = true;
    this.health = this.maxHealth;
    this.stamina = this.maxStamina;
    this.pos.set(SPAWN.x, heightAt(SPAWN.x, SPAWN.z), SPAWN.z);
    this.vel.set(0, 0, 0);
    this.facing = Math.PI;
    this.character.setVisible(true);
    this.character.root.position.copy(this.pos);
    this.invuln = 2;
    this.ui.hideDeath();
    this.ui.toast('Angin membawamu kembali', '✦');
    this.statsDirty = true;
  }

  update(dt, input, camYaw, elapsed) {
    if (!this.alive) {
      this.character.update(dt, { speed: 0, onGround: true, elapsed });
      return;
    }

    this.invuln = Math.max(0, this.invuln - dt);
    this.cooldowns[0] = Math.max(0, this.cooldowns[0] - dt);
    this.cooldowns[1] = Math.max(0, this.cooldowns[1] - dt);
    this.shake = Math.max(0, this.shake - dt * 2.4);
    this.flash = Math.max(0, this.flash - dt * 3.2);

    for (let i = this.pendingMeteors.length - 1; i >= 0; i--) {
      const meteor = this.pendingMeteors[i];
      meteor.delay -= dt;
      if (meteor.delay <= 0) {
        this.spawnMeteor(meteor.offset);
        this.pendingMeteors.splice(i, 1);
      }
    }

    // ---- movement ----
    const f = this.tmp.set(-Math.sin(camYaw), 0, -Math.cos(camYaw));
    const rightX = Math.cos(camYaw);
    const rightZ = -Math.sin(camYaw);
    let mx = f.x * input.y + rightX * input.x;
    let mz = f.z * input.y + rightZ * input.x;
    const inLen = Math.hypot(mx, mz);
    if (inLen > 1) {
      mx /= inLen;
      mz /= inLen;
    }
    const inputLen = Math.min(1, inLen);
    this.moveDir.set(mx, 0, mz);

    const ground = heightAt(this.pos.x, this.pos.z);
    const depth = WATER_Y - ground;
    const wasSwimming = this.swimming;
    this.swimming = depth > 0.85 && this.pos.y < WATER_Y + 0.5;
    if (this.swimming && !wasSwimming) {
      this.gliding = false;
    }

    const wantsSprint = input.sprint && inputLen > 0.2 && this.onGround && !this.swimming;
    this.sprinting = wantsSprint && this.stamina > 0.5;

    let speed;
    if (this.swimming) speed = this.stamina > 0 ? 4.2 : 2.4;
    else if (this.sprinting) speed = 9.1;
    else speed = 5.7;
    if (this.gliding) speed = 7.6;

    let slopePenalty = 1;
    if (this.onGround && !this.swimming) {
      const slope = slopeAt(this.pos.x, this.pos.z);
      slopePenalty = clamp(1 - (slope - 0.45) * 0.32, 0.55, 1);
    }

    const targetVX = mx * speed * slopePenalty;
    const targetVZ = mz * speed * slopePenalty;
    const accel = this.swimming ? 5 : this.onGround ? 13 : this.gliding ? 4.5 : 4;
    this.vel.x = damp(this.vel.x, targetVX, accel, dt);
    this.vel.z = damp(this.vel.z, targetVZ, accel, dt);
    if (this.swimming) this.vel.y = 0;

    // ---- jump / glide ----
    if (input.jumpPressed && this.onGround && !this.swimming) {
      this.vel.y = 8.9;
      this.onGround = false;
      this.airTime = 0;
      this.stamina = Math.max(0, this.stamina - 6);
      this.staminaDelay = 0.7;
      this.audio.sfx('jump');
    }

    if (!this.onGround && input.jumpHeld && !this.swimming && this.vel.y < 2 && this.airTime > 0.18 && this.stamina > 2) {
      if (!this.gliding) {
        this.gliding = true;
        this.fx.spark(this.pos.clone().add(new THREE.Vector3(0, 0.2, 0)), 'anemo', { count: 18, speed: 3, size: 0.4, life: 0.6, gravity: 0, up: 0.2 });
      }
    }
    if (this.gliding && (!input.jumpHeld || this.stamina <= 0 || this.onGround)) {
      this.gliding = false;
    }

    if (this.swimming) {
      this.pos.y = damp(this.pos.y, WATER_Y + 0.12, 8, dt);
      this.onGround = false;
      this.airTime = 0;
      this.gliding = false;
      this.stamina = Math.max(0, this.stamina - 3.5 * dt);
      this.staminaDelay = 0.8;
    } else {
      if (this.gliding) {
        this.vel.y = Math.max(this.vel.y - GRAVITY * 0.14 * dt, -2.4);
        this.stamina = Math.max(0, this.stamina - 5.5 * dt);
        this.staminaDelay = 0.8;
      } else {
        this.vel.y -= GRAVITY * dt;
      }
      const wasGrounded = this.onGround;
      this.pos.y += this.vel.y * dt;
      const g = heightAt(this.pos.x, this.pos.z);
      if (this.pos.y <= g) {
        if (!wasGrounded && this.vel.y < -9) {
          this.audio.sfx('land');
          this.fx.particles.spawn(this.pos.clone().add(new THREE.Vector3(0, 0.05, 0)), '#cdbf9a', {
            count: 10,
            speed: 1.6,
            size: 0.18,
            life: 0.5,
            gravity: -0.5,
            up: 0.2,
            radius: 0.2,
          });
        }
        this.pos.y = g;
        this.vel.y = 0;
        this.onGround = true;
        this.airTime = 0;
        if (this.gliding) this.gliding = false;
      } else {
        this.onGround = false;
        this.airTime += dt;
      }
    }

    // Horizontal movement + boundary.
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    const radial = Math.hypot(this.pos.x, this.pos.z);
    if (radial > WORLD_RADIUS + 2) {
      const k = (WORLD_RADIUS + 2) / radial;
      this.pos.x *= k;
      this.pos.z *= k;
      this.vel.x *= 0.4;
      this.vel.z *= 0.4;
    }

    if (this.onGround && !this.swimming) {
      this.pos.y = heightAt(this.pos.x, this.pos.z);
    }

    // ---- stamina ----
    if (this.sprinting) {
      this.stamina = Math.max(0, this.stamina - 13 * dt);
      this.staminaDelay = 0.7;
    }
    if (this.stamina <= 0) {
      this.sprinting = false;
      if (this.gliding) this.gliding = false;
    }
    const regen = !this.sprinting && !this.gliding && !this.swimming;
    if (regen) {
      this.staminaDelay = Math.max(0, this.staminaDelay - dt);
      if (this.staminaDelay <= 0) this.stamina = Math.min(this.maxStamina, this.stamina + 18 * dt);
    }

    // ---- facing ----
    const speed2 = Math.hypot(this.vel.x, this.vel.z);
    if (this.attackTime < 0 && this.castTime <= 0 && speed2 > 0.4 && inputLen > 0.1) {
      this.facing = angleLerp(this.facing, Math.atan2(this.vel.x, this.vel.z), Math.min(1, dt * 12));
    }
    this.character.root.rotation.y = this.facing;

    // ---- attacks ----
    if (input.attackPressed && !this.swimming) {
      this.tryAttack();
    }
    if (this.attackTime >= 0) {
      this.attackTime += dt;
      if (!this.attackHit && this.attackTime >= 0.16) {
        this.attackHit = true;
        this.applyAttackHit();
      }
      if (this.attackTime >= this.attackDuration) {
        if (this.attackQueued) {
          this.startAttack();
        } else {
          this.attackTime = -1;
          this.combo = -1;
          this.attackQueued = false;
        }
      }
    }
    if (this.castTime > 0) {
      this.castTime -= dt;
      if (this.character.anim.cast >= 0) this.character.anim.cast = 1 - this.castTime / this.castDuration;
      if (this.castTime <= 0) this.character.anim.cast = -1;
    }

    if (input.skillPressed) this.useSkill();
    if (input.burstPressed) this.useBurst();

    // ---- world interactions ----
    const statueDist = Math.hypot(this.pos.x - STATUE_POS.x, this.pos.z - STATUE_POS.z);
    if (statueDist < 5.2 && this.health < this.maxHealth) {
      this.heal(16 * dt, { silent: false, fx: false });
      this.healFxTimer -= dt;
      if (this.healFxTimer <= 0) {
        this.healFxTimer = 0.55;
        this.fx.heal(this.pos.clone().add(new THREE.Vector3(0, 1, 0)));
        this.fx.floatText(this.pos.clone().add(new THREE.Vector3(0, 1.7, 0)), '+16', { kind: 'heal' });
        this.audio.sfx('heal');
      }
      if (!this.nearStatue) {
        this.nearStatue = true;
        this.ui.toast('Diberkati oleh <b>Patung Angin</b>', '✦');
      }
    } else {
      this.nearStatue = false;
    }

    // Out-of-combat regeneration keeps the exploration loop forgiving.
    const now = performance.now() / 1000;
    if (now - this.lastDamageAt > 12 && this.health < this.maxHealth && !this.nearStatue) {
      this.heal(1.8 * dt, { silent: true });
    }

    // ---- animation ----
    this.character.anim.attack = this.attackTime >= 0 ? this.attackTime / this.attackDuration : -1;
    if (this.castTime > 0) this.character.anim.cast = 1 - this.castTime / this.castDuration;
    this.character.root.position.copy(this.pos);
    this.character.update(dt, {
      speed: speed2,
      onGround: this.onGround,
      gliding: this.gliding,
      swimming: this.swimming,
      elapsed,
    });

    // run dust, glide trails, footstep audio
    if (this.onGround && speed2 > 5.5) {
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = this.sprinting ? 0.22 : 0.34;
        this.fx.particles.spawn(
          this.pos.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.4, 0.08, (Math.random() - 0.5) * 0.4)),
          '#d8cba6',
          { count: 2, speed: 0.7, size: 0.16, life: 0.42, gravity: 1, up: 0.35, radius: 0.1 }
        );
      }
    }
    if (this.gliding) {
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = 0.05;
        this.fx.particles.spawn(
          this.pos.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.8, 0.5, (Math.random() - 0.5) * 0.8)),
          ELEMENT_COLORS.anemo,
          { count: 1, speed: 1.2, size: 0.22, life: 0.55, gravity: -0.2, up: 0.6, radius: 0 }
        );
      }
    }

    this.statsDirty = true;
  }

  stats() {
    return {
      health: this.health,
      maxHealth: this.maxHealth,
      stamina: this.stamina,
      maxStamina: this.maxStamina,
      energy: this.energy[this.active],
      maxEnergy: this.maxEnergy,
      cooldown: this.cooldowns[this.active],
      maxCooldown: this.data.element === 'anemo' ? 7 : 6,
      active: this.active,
      element: this.data.element,
      name: this.data.name,
      level: this.level,
      alive: this.alive,
      gliding: this.gliding,
      sprinting: this.sprinting,
      swimming: this.swimming,
    };
  }
}

