export class Quest {
  constructor(game) {
    this.game = game;
    this.step = 0;
    this.wispCount = 0;
    this.killCount = 0;
    this.started = false;
    this.rewardShown = false;
    this.repeatIndex = 0;
    this.markerPos = new THREE.Vector3();
  }

  start() {
    this.started = true;
    this.step = 0;
    this.refresh();
    this.game.ui.toast('Petualangan dimulai · <b>Jejak Sang Angin</b>', '◆');
  }

  refresh() {
    const info = STEPS[this.step];
    const current = this.step === 1 ? this.wispCount : this.step === 2 ? this.killCount : 0;
    this.game.ui.setQuest({
      title: info.title,
      desc: info.desc,
      current,
      total: info.total,
    });
  }

  advance(step) {
    this.step = step;
    if (step === 2) this.killCount = 0;
    this.refresh();
    this.game.audio.sfx('quest');
    if (step === 2) this.game.ui.toast('Serpihan lengkap! Sekarang bersihkan <b>3 slime</b>.', '◆');
    if (step === 3) this.game.ui.toast('Jalan ke puncak terbuka. <b>Buka peti kuno</b>!', '◆');
    if (step === 4) this.game.ui.toast('Badai mereda. <b>Aetheria</b> kembali damai.', '✦');
  }

  update(playerPos) {
    if (!this.started) return;

    // Serpihan Angin are collected by walking into their glow.
    if (this.step === 1) {
      this.game.world.wisps.forEach((wisp, i) => {
        if (wisp.userData.collected) return;
        const d = Math.hypot(wisp.position.x - playerPos.x, wisp.position.z - playerPos.z);
        if (d < 2.1) {
          const pos = this.game.world.collectWisp(i) || wisp.position.clone();
          this.wispCount++;
          this.game.fx.burst(pos, 'anemo', 40);
          this.game.fx.pickup(pos, '#8cf0dd');
          this.game.audio.sfx('pickup');
          this.game.ui.toast(`Serpihan Angin <b>${this.wispCount}/3</b>`, '✦');
          this.game.player.energy[this.game.player.active] = Math.min(
            this.game.player.maxEnergy,
            this.game.player.energy[this.game.player.active] + 8
          );
          this.refresh();
          if (this.wispCount >= 3) {
            setTimeout(() => this.advance(2), 550);
          }
        }
      });
    }
  }

  onKill(enemy) {
    if (this.step !== 2 || enemy.boss) return;
    this.killCount++;
    this.refresh();
    this.game.ui.toast(`Slime dikalahkan <b>${this.killCount}/3</b>`, '⚔');
    if (this.killCount >= 3) setTimeout(() => this.advance(3), 450);
  }

  getMarker() {
    if (!this.started) return null;
    if (this.step === 0) {
      return { pos: new THREE.Vector3(NPC_POS.x, heightAt(NPC_POS.x, NPC_POS.z) + 2.8, NPC_POS.z), label: 'Penjaga Awan' };
    }
    if (this.step === 1) {
      const wisp = this.game.world.wisps.find((w) => !w.userData.collected);
      if (!wisp) return null;
      return { pos: wisp.position.clone().add(new THREE.Vector3(0, 1.4, 0)), label: 'Serpihan Angin' };
    }
    if (this.step === 2) {
      const slime = this.game.enemies.nearest(this.game.player.pos, 999);
      if (!slime) return null;
      return { pos: slime.pos.clone().add(new THREE.Vector3(0, 2.2, 0)), label: 'Slime' };
    }
    if (this.step === 3 && !this.game.world.chestOpened()) {
      return { pos: new THREE.Vector3(CHEST_POS.x, heightAt(CHEST_POS.x, CHEST_POS.z) + 2.1, CHEST_POS.z), label: 'Peti Kuno' };
    }
    return null;
  }

  nearestInteraction(playerPos) {
    const list = [];
    const npcD = Math.hypot(playerPos.x - NPC_POS.x, playerPos.z - NPC_POS.z);
    if (npcD < 3.5) {
      list.push({ type: 'npc', dist: npcD, label: this.step === 0 ? 'Bicara dengan Penjaga' : 'Bicara' });
    }
    const statueD = Math.hypot(playerPos.x - STATUE_POS.x, playerPos.z - STATUE_POS.z);
    if (statueD < 4.6) {
      list.push({ type: 'statue', dist: statueD + 0.5, label: 'Berdoa di Patung Angin' });
    }
    const chestD = Math.hypot(playerPos.x - CHEST_POS.x, playerPos.z - CHEST_POS.z);
    if (chestD < 3.8 && !this.game.world.chestOpened()) {
      list.push({
        type: 'chest',
        dist: chestD,
        label: this.step >= 3 ? 'Buka Peti Kuno' : 'Peti Tersegel',
      });
    }
    list.sort((a, b) => a.dist - b.dist);
    return list[0] || null;
  }

  interact(playerPos) {
    const target = this.nearestInteraction(playerPos);
    if (!target) return;
    if (target.type === 'npc') {
      const lines = this.step === 0 ? ELDER_LINES : [ELDER_REPEAT[this.repeatIndex++ % ELDER_REPEAT.length]];
      this.game.ui.startDialogue('Penjaga Awan', lines, () => {
        if (this.step === 0) this.advance(1);
      });
    } else if (target.type === 'statue') {
      this.game.player.heal(999, { fx: true });
      this.game.audio.sfx('heal');
      this.game.ui.toast('Luka dipulihkan oleh <b>Patung Angin</b>', '✦');
    } else if (target.type === 'chest') {
      if (this.step < 3) {
        this.game.audio.sfx('ui');
        this.game.ui.toast('Peti ini disegel. Selesaikan tugas penjaga dahulu.', '🔒');
        return;
      }
      const pos = this.game.world.openChest();
      this.game.fx.burst(pos.clone().add(new THREE.Vector3(0, 0.8, 0)), 'pyro', 60);
      this.game.fx.pickup(pos.clone().add(new THREE.Vector3(0, 1, 0)), '#f3d998');
      this.game.fx.shockwave(pos, '#f3d998', 6, { life: 0.8 });
      this.game.audio.sfx('chest');
      this.game.player.energy[this.game.player.active] = this.game.player.maxEnergy;
      this.game.ui.toast('Peti kuno terbuka!', '✦');
      this.advance(4);
      setTimeout(() => this.game.ui.showReward(), 850);
      this.rewardShown = true;
    }
  }

  isDone() {
    return this.step >= 4;
  }
}

import { heightAt, slopeAt, WORLD_RADIUS, STATUE_POS, NPC_POS, CHEST_POS, WISP_SPOTS } from './world.js';

const $ = (id) => document.getElementById(id);

export class UI {
  constructor(game) {
    this.game = game;
    this.el = {
      loading: $('loading'),
      loadingFill: $('loading-fill'),
      loadingText: $('loading-text'),
      title: $('title'),
      hud: $('hud'),
      questTitle: $('quest-title'),
      questDesc: $('quest-desc'),
      questProgress: $('quest-progress'),
      questProgressFill: $('quest-progress').querySelector('i'),
      questProgressText: $('quest-progress').querySelector('span'),
      marker: $('objective-marker'),
      markerDist: $('marker-dist'),
      interact: $('interact'),
      interactText: $('interact-text'),
      staminaWrap: $('stamina-wrap'),
      stamina: $('stamina').querySelector('i'),
      hp: document.querySelectorAll('.char-hp i'),
      party: document.querySelectorAll('.char-chip'),
      skill: $('btn-skill'),
      burst: $('btn-burst'),
      attack: $('btn-attack'),
      jump: $('btn-jump'),
      skillCd: $('btn-skill').querySelector('.cd'),
      burstEnergy: $('btn-burst').querySelector('.energy-pip'),
      toastStack: $('toast-stack'),
      damageLayer: $('damage-layer'),
      enemyBars: $('enemy-bars'),
      reaction: $('reaction-pop'),
      bossBar: $('boss-bar'),
      bossFill: $('boss-fill'),
      bossName: $('boss-name'),
      bossElement: $('boss-element'),
      dialogue: $('dialogue'),
      dialogueName: $('dialogue-name'),
      dialogueText: $('dialogue-text'),
      dialogueNext: $('dialogue-next'),
      reward: $('reward'),
      rewardClose: $('reward-close'),
      pause: $('pause'),
      death: $('death'),
      deathRespawn: $('death-respawn'),
      flash: $('flash'),
      lowHp: $('low-hp'),
      minimap: $('minimap'),
      minimapLabel: $('minimap-label'),
    };
    this.ctx = this.el.minimap.getContext('2d');
    this.dialogueLines = [];
    this.dialogueIndex = 0;
    this.dialogueTimer = null;
    this.dialogueTyping = false;
    this.dialogueFull = '';
    this.dialogueChar = 0;
    this.dialogueOnDone = null;
    this.dialogueActive = false;
    this.mapCanvas = null;
    this.mapScale = 1;
    this.mapExtent = 110;
    this.reactionTimer = null;
    this.isTouch = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    if (this.isTouch) document.body.classList.add('touch');
    this.buildMap();
    this.bind();
    this.createHurtFlash();
  }

  createHurtFlash() {
    const el = document.createElement('div');
    el.id = 'hurt-flash';
    el.style.cssText = `
      position:fixed;inset:0;pointer-events:none;z-index:29;opacity:0;
      background:radial-gradient(ellipse at center, transparent 38%, rgba(200,25,30,.6) 100%);
      transition:opacity .45s ease;
    `;
    document.body.appendChild(el);
    this.hurtFlash = el;
  }

  buildMap() {
    const size = 256;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const img = ctx.createImageData(size, size);
    const extent = this.mapExtent;
    const waterDeep = [12, 48, 63];
    const waterShallow = [45, 111, 122];
    const sand = [203, 189, 141];
    const grass = [95, 138, 77];
    const grassDark = [69, 110, 66];
    const rock = [138, 136, 123];
    const highRock = [185, 177, 156];

    for (let py = 0; py < size; py++) {
      for (let px = 0; px < size; px++) {
        const wx = (px / size) * extent * 2 - extent;
        const wz = (py / size) * extent * 2 - extent;
        const h = heightAt(wx, wz);
        const slope = slopeAt(wx, wz);
        let c;
        if (h < 0) {
          const t = Math.min(1, -h / 7);
          c = mix(waterShallow, waterDeep, t);
        } else if (h < 1.6) {
          c = mix(sand, grass, Math.min(1, h / 2.2) * 0.35);
        } else {
          c = mix(grass, grassDark, Math.min(1, h / 26) * 0.55);
          if (slope > 0.6) c = mix(c, rock, Math.min(1, (slope - 0.6) * 1.6));
          if (h > 20) c = mix(c, highRock, Math.min(1, (h - 20) / 12) * 0.7);
        }
        const shade = 0.92 + Math.sin(wx * 0.3 + wz * 0.2) * 0.04;
        const i = (py * size + px) * 4;
        img.data[i] = Math.min(255, c[0] * shade);
        img.data[i + 1] = Math.min(255, c[1] * shade);
        img.data[i + 2] = Math.min(255, c[2] * shade);
        img.data[i + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);

    const upscale = document.createElement('canvas');
    upscale.width = upscale.height = 512;
    const uctx = upscale.getContext('2d');
    uctx.imageSmoothingEnabled = true;
    uctx.drawImage(canvas, 0, 0, 512, 512);
    this.mapCanvas = upscale;
    this.mapScale = 512 / (extent * 2);

    function mix(a, b, t) {
      return [
        a[0] + (b[0] - a[0]) * t,
        a[1] + (b[1] - a[1]) * t,
        a[2] + (b[2] - a[2]) * t,
      ];
    }
  }

  bind() {
    this.el.dialogueNext.addEventListener('click', () => this.advanceDialogue());
    this.el.interact.addEventListener('click', () => {
      if (this.game.mode === 'playing') this.game.interact();
    });
    this.el.rewardClose.addEventListener('click', () => this.hideReward());
    this.el.deathRespawn.addEventListener('click', () => this.game.respawnPlayer());
    window.addEventListener('keydown', (event) => {
      if (!this.dialogueActive) return;
      if (event.code === 'Enter' || event.code === 'Space' || event.code === 'KeyF') {
        event.preventDefault();
        event.stopPropagation();
        this.advanceDialogue();
      }
    }, true);
  }

  setLoading(progress, text) {
    this.el.loadingFill.style.width = `${Math.round(progress * 100)}%`;
    if (text) this.el.loadingText.textContent = text;
  }

  hideLoading() {
    this.el.loading.classList.add('hidden');
  }

  showTitle() {
    this.el.title.classList.remove('hidden');
  }

  hideTitle() {
    this.el.title.classList.add('hidden');
  }

  showHud() {
    this.el.hud.classList.remove('hidden');
  }

  setQuest({ title, desc, current, total }) {
    this.el.questTitle.textContent = title;
    this.el.questDesc.textContent = desc;
    if (total > 0) {
      this.el.questProgress.classList.remove('hidden');
      this.el.questProgressFill.style.setProperty('--p', `${Math.min(100, (current / total) * 100)}%`);
      this.el.questProgressText.textContent = `${current} / ${total}`;
    } else {
      this.el.questProgress.classList.add('hidden');
    }
  }

  updateParty(player) {
    this.el.party.forEach((chip, index) => {
      chip.classList.toggle('active', index === player.active);
      this.el.hp[index].style.width = `${Math.max(0, (player.health / player.maxHealth) * 100)}%`;
    });
  }

  setElement(element) {
    document.body.classList.toggle('pyro', element === 'pyro');
  }

  updateAbilities(stats) {
    const cd = stats.cooldown;
    this.el.skillCd.textContent = cd > 0.05 ? String(Math.ceil(cd)) : '';
    this.el.skillCd.style.height = cd > 0.05 ? `${Math.min(100, (cd / stats.maxCooldown) * 100)}%` : '0%';
    this.el.skill.classList.toggle('ready', cd <= 0.05);

    const energyPct = Math.min(100, (stats.energy / stats.maxEnergy) * 100);
    this.el.burstEnergy.style.setProperty('--energy', `${energyPct}%`);
    this.el.burst.classList.toggle('ready', energyPct >= 99.5);

    this.el.stamina.style.width = `${Math.max(0, (stats.stamina / stats.maxStamina) * 100)}%`;
    const showStamina = stats.stamina < stats.maxStamina - 1 || stats.gliding || stats.swimming || stats.sprinting;
    this.el.staminaWrap.classList.toggle('hidden', !showStamina);

    this.el.lowHp.classList.toggle('on', stats.health > 0 && stats.health < 30);
    this.setElement(stats.element);
  }

  setInteraction(interaction) {
    if (!interaction) {
      this.el.interact.classList.add('hidden');
      return;
    }
    this.el.interact.classList.remove('hidden');
    this.el.interactText.textContent = interaction.label;
  }

  updateMarker(marker, camera) {
    if (!marker) {
      this.el.marker.classList.add('hidden');
      return;
    }
    const v = marker.pos.clone();
    const dist = Math.hypot(v.x - this.game.player.pos.x, v.z - this.game.player.pos.z);
    v.project(camera);
    if (v.z > 1 || v.z < -1 || Math.abs(v.x) > 1.12 || Math.abs(v.y) > 1.12 || dist < 2) {
      this.el.marker.classList.add('hidden');
      return;
    }
    this.el.marker.classList.remove('hidden');
    this.el.marker.style.left = `${(v.x * 0.5 + 0.5) * window.innerWidth}px`;
    this.el.marker.style.top = `${(-v.y * 0.5 + 0.5) * window.innerHeight}px`;
    this.el.markerDist.textContent = `${Math.round(dist)} m`;
  }

  updateBoss(boss, camera, playerPos) {
    if (!boss) {
      this.el.bossBar.classList.add('hidden');
      return;
    }
    const dist = Math.hypot(boss.pos.x - playerPos.x, boss.pos.z - playerPos.z);
    if (dist > 30) {
      this.el.bossBar.classList.add('hidden');
      return;
    }
    this.el.bossBar.classList.remove('hidden');
    this.el.bossFill.style.width = `${Math.max(0, (boss.hp / boss.maxHp) * 100)}%`;
  }

  showReaction(text) {
    this.el.reaction.textContent = text;
    this.el.reaction.classList.remove('show');
    void this.el.reaction.offsetWidth;
    this.el.reaction.classList.add('show');
    clearTimeout(this.reactionTimer);
    this.reactionTimer = setTimeout(() => this.el.reaction.classList.remove('show'), 1600);
  }

  toast(html, icon = '✦') {
    while (this.el.toastStack.children.length >= 4) {
      this.el.toastStack.firstElementChild.remove();
    }
    const el = document.createElement('div');
    el.className = 'toast';
    el.innerHTML = `<span class="toast-icon">${icon}</span><span>${html}</span>`;
    this.el.toastStack.appendChild(el);
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 420);
    }, 3200);
  }

  flashScreen() {
    this.el.flash.classList.add('on');
    setTimeout(() => this.el.flash.classList.remove('on'), 80);
  }

  damageFlash() {
    this.hurtFlash.style.opacity = '1';
    setTimeout(() => { this.hurtFlash.style.opacity = '0'; }, 130);
  }

  showDeath() {
    this.el.death.classList.remove('hidden');
    this.game.mode = 'dead';
  }

  hideDeath() {
    this.el.death.classList.add('hidden');
    this.game.mode = 'playing';
  }

  showReward() {
    this.el.reward.classList.remove('hidden');
    this.game.mode = 'reward';
  }

  hideReward() {
    this.el.reward.classList.add('hidden');
    this.game.mode = 'playing';
  }

  openPause() {
    this.el.pause.classList.remove('hidden');
    this.game.mode = 'paused';
  }

  closePause() {
    this.el.pause.classList.add('hidden');
    this.game.mode = 'playing';
  }

  startDialogue(name, lines, onDone) {
    this.dialogueLines = lines;
    this.dialogueIndex = 0;
    this.dialogueOnDone = onDone;
    this.dialogueActive = true;
    this.el.dialogueName.textContent = name;
    this.el.dialogue.classList.remove('hidden');
    this.game.mode = 'dialogue';
    this.typeDialogue(lines[0]);
  }

  typeDialogue(text) {
    clearInterval(this.dialogueTimer);
    this.dialogueFull = text;
    this.dialogueChar = 0;
    this.dialogueTyping = true;
    this.el.dialogueText.textContent = '';
    this.dialogueTimer = setInterval(() => {
      this.dialogueChar += 1;
      this.el.dialogueText.textContent = text.slice(0, this.dialogueChar);
      if (this.dialogueChar % 5 === 0) this.game.audio.sfx('dialogue');
      if (this.dialogueChar >= text.length) {
        clearInterval(this.dialogueTimer);
        this.dialogueTyping = false;
      }
    }, 18);
  }

  advanceDialogue() {
    if (!this.dialogueActive) return;
    if (this.dialogueTyping) {
      clearInterval(this.dialogueTimer);
      this.dialogueTyping = false;
      this.el.dialogueText.textContent = this.dialogueFull;
      return;
    }
    this.dialogueIndex++;
    if (this.dialogueIndex >= this.dialogueLines.length) {
      this.endDialogue();
      return;
    }
    this.typeDialogue(this.dialogueLines[this.dialogueIndex]);
  }

  endDialogue() {
    clearInterval(this.dialogueTimer);
    this.dialogueTyping = false;
    this.dialogueActive = false;
    this.el.dialogue.classList.add('hidden');
    this.game.mode = 'playing';
    const cb = this.dialogueOnDone;
    this.dialogueOnDone = null;
    cb?.();
  }

  drawMinimap(player, quest, enemies, cameraYaw) {
    const ctx = this.ctx;
    const size = this.el.minimap.width;
    const viewR = 48;
    const px = player.pos.x;
    const pz = player.pos.z;

    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 2, 0, Math.PI * 2);
    ctx.clip();

    ctx.fillStyle = '#0d3343';
    ctx.fillRect(0, 0, size, size);

    const sw = viewR * 2 * this.mapScale;
    const sx = (px + this.mapExtent - viewR) * this.mapScale;
    const sy = (pz + this.mapExtent - viewR) * this.mapScale;
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(this.mapCanvas, sx, sy, sw, sw, 0, 0, size, size);

    const toScreen = (wx, wz) => ({
      x: ((wx - (px - viewR)) / (viewR * 2)) * size,
      y: ((wz - (pz - viewR)) / (viewR * 2)) * size,
    });

    const near = (p) => Math.hypot(p.x - px, p.z - pz) < viewR;

    // enemies
    for (const e of enemies.enemies) {
      if (e.dead) continue;
      if (!near(e.pos)) continue;
      const s = toScreen(e.pos.x, e.pos.z);
      ctx.beginPath();
      ctx.arc(s.x, s.y, e.boss ? 7 : 3.3, 0, Math.PI * 2);
      ctx.fillStyle = e.boss ? '#ff8b5e' : '#ff6961';
      ctx.fill();
      if (e.boss) {
        ctx.strokeStyle = 'rgba(255,255,255,.7)';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }
    }

    // wisps
    for (const wisp of this.game.world.wisps) {
      if (wisp.userData.collected || !near(wisp.position)) continue;
      const s = toScreen(wisp.position.x, wisp.position.z);
      ctx.beginPath();
      ctx.arc(s.x, s.y, 3, 0, Math.PI * 2);
      ctx.fillStyle = '#8cf0dd';
      ctx.shadowColor = '#8cf0dd';
      ctx.shadowBlur = 8;
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    const point = (wx, wz, color, radius, stroke = false) => {
      if (!near({ x: wx, z: wz })) return;
      const s = toScreen(wx, wz);
      ctx.beginPath();
      ctx.arc(s.x, s.y, radius, 0, Math.PI * 2);
      ctx.fillStyle = color;
      ctx.fill();
      if (stroke) {
        ctx.strokeStyle = 'rgba(255,255,255,.75)';
        ctx.lineWidth = 1.2;
        ctx.stroke();
      }
    };

    point(NPC_POS.x, NPC_POS.z, '#f3d998', 3.6, true);
    point(STATUE_POS.x, STATUE_POS.z, '#8cf0dd', 4, true);
    if (!this.game.world.chestOpened()) point(CHEST_POS.x, CHEST_POS.z, '#ffcf7a', 4, true);

    // current quest target (clamped to the rim when off-map)
    const marker = quest.getMarker();
    if (marker) {
      const s = toScreen(marker.pos.x, marker.pos.z);
      const dx = s.x - size / 2;
      const dy = s.y - size / 2;
      const d = Math.hypot(dx, dy);
      const maxR = size / 2 - 16;
      let mx = s.x;
      let my = s.y;
      if (d > maxR) {
        mx = size / 2 + (dx / d) * maxR;
        my = size / 2 + (dy / d) * maxR;
      }
      const pulse = 1 + Math.sin(performance.now() / 260) * 0.18;
      ctx.save();
      ctx.translate(mx, my);
      ctx.rotate(Math.PI / 4);
      ctx.fillStyle = '#f3d998';
      ctx.shadowColor = '#f3d998';
      ctx.shadowBlur = 10;
      ctx.fillRect(-5.2 * pulse, -5.2 * pulse, 10.4 * pulse, 10.4 * pulse);
      ctx.restore();
    }

    // player arrow
    const yaw = player.facing;
    const fx = Math.sin(yaw);
    const fz = Math.cos(yaw);
    const rx = Math.cos(yaw);
    const rz = -Math.sin(yaw);
    const cx = size / 2;
    const cy = size / 2;
    ctx.beginPath();
    ctx.moveTo(cx + fx * 12, cy + fz * 12);
    ctx.lineTo(cx - fx * 7 + rx * 7, cy - fz * 7 + rz * 7);
    ctx.lineTo(cx - fx * 4, cy - fz * 4);
    ctx.lineTo(cx - fx * 7 - rx * 7, cy - fz * 7 - rz * 7);
    ctx.closePath();
    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = '#8cf0dd';
    ctx.shadowBlur = 10;
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = 'rgba(10,30,40,.8)';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    // camera view cone
    const camDir = cameraYaw + Math.PI;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, 34, camDir - Math.PI / 2 - 0.44, camDir - Math.PI / 2 + 0.44);
    ctx.closePath();
    const g = ctx.createRadialGradient(cx, cy, 4, cx, cy, 34);
    g.addColorStop(0, 'rgba(220,255,250,.18)');
    g.addColorStop(1, 'rgba(220,255,250,0)');
    ctx.fillStyle = g;
    ctx.fill();

    ctx.restore();

    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 2, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(243,217,152,.22)';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  updateHud(stats, player) {
    this.updateAbilities(stats);
    if (player) this.updateParty(player);
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { createWorld, heightAt, SPAWN, WATER_Y } from './world.js';
import { Player } from './player.js';
import { EnemyManager } from './enemies.js';
import { Quest } from './quest.js';
import { UI } from './ui.js';
import { FX } from './fx.js';
import { AudioEngine } from './audio.js';
import { clamp, damp } from './look.js';

const canvas = document.getElementById('game');
const params = new URLSearchParams(location.search);

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: 'high-performance',
});
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.04;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

let detectedQuality = 'high';
try {
  const gl = renderer.getContext();
  const debug = gl.getExtension('WEBGL_debug_renderer_info');
  const name = debug ? String(gl.getParameter(debug.UNMASKED_RENDERER_WEBGL)) : '';
  if (/swiftshader|software|llvmpipe|basic render/i.test(name)) detectedQuality = 'low';
  else if (window.matchMedia('(pointer: coarse)').matches) detectedQuality = 'medium';
} catch {}

const quality = ['low', 'medium', 'high'].includes(params.get('quality'))
  ? params.get('quality')
  : detectedQuality;

const pixelRatio = () =>
  Math.min(window.devicePixelRatio || 1, quality === 'high' ? 2 : quality === 'medium' ? 1.5 : 1);

renderer.setPixelRatio(pixelRatio());
renderer.setSize(window.innerWidth, window.innerHeight);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.12, 760);
camera.userData.yaw = 0;

const fx = new FX(scene, camera);
const audio = new AudioEngine();

const game = {
  mode: 'loading',
  quality,
  scene,
  camera,
  renderer,
  fx,
  audio,
  elapsed: 0,
  qualityIndex: ['low', 'medium', 'high'].indexOf(quality),
};

const clock = { last: performance.now() };
const camState = { yaw: 0, pitch: 0.28, dist: 7.4, targetDist: 7.4 };
const keys = new Set();
const joy = { x: 0, y: 0, active: false, pointerId: null };
const input = {
  x: 0,
  y: 0,
  sprint: false,
  jumpPressed: false,
  jumpHeld: false,
  attackPressed: false,
  skillPressed: false,
  burstPressed: false,
  interactPressed: false,
};
let touchJumpHeld = false;
let drag = null;
let ui = null;
let world = null;
let player = null;
let enemies = null;
let quest = null;
let composer = null;
let bloom = null;
let minimapTimer = 0;
let currentInteraction = null;
let booted = false;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function boot() {
  ui = new UI(game);
  game.ui = ui;
  ui.setLoading(0.08, 'Menenun angin...');
  await sleep(40);

  ui.setLoading(0.22, 'Mengangkat pulau dari laut...');
  await sleep(30);
  world = createWorld(scene, { quality });
  game.world = world;

  ui.setLoading(0.55, 'Menumbuhkan hutan Aetheria...');
  await sleep(30);

  enemies = new EnemyManager({
    scene,
    fx,
    audio,
    ui,
    camera,
    onKill: (enemy) => handleKill(enemy),
  });
  game.enemies = enemies;

  player = new Player({ scene, camera, world, fx, enemies, audio, ui });
  game.player = player;

  quest = new Quest(game);
  game.quest = quest;

  ui.setLoading(0.82, 'Membangunkan elemen purba...');
  await sleep(30);

  if (quality === 'high') {
    try {
      composer = new EffectComposer(renderer);
      composer.addPass(new RenderPass(scene, camera));
      bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.3, 0.55, 0.9);
      composer.addPass(bloom);
    } catch (error) {
      composer = null;
    }
  }

  // A pleasant establishing shot before the player takes control.
  player.character.root.position.copy(player.pos);
  player.character.root.rotation.y = player.facing;
  player.character.update(0.016, { speed: 0, onGround: true, elapsed: 0 });

  camState.yaw = 0.55;
  camState.pitch = 0.24;
  camState.dist = 8.2;
  camState.targetDist = 8.2;
  updateCamera(0.016, true);

  ui.setLoading(0.95, 'Menajamkan bilah...');
  await sleep(30);
  ui.setLoading(1, 'Aetheria siap.');
  await sleep(280);

  ui.hideLoading();
  ui.showTitle();
  game.mode = 'title';
  booted = true;
  clock.last = performance.now();
  requestAnimationFrame(loop);
}

function handleKill(enemy) {
  quest?.onKill(enemy);
  if (player) {
    const gain = enemy.boss ? 24 : 15;
    player.energy[player.active] = Math.min(player.maxEnergy, player.energy[player.active] + gain);
  }
}

function startGame() {
  if (game.mode !== 'title' || !booted) return;
  audio.init();
  audio.sfx('ui');
  ui.hideTitle();
  ui.showHud();
  player.character.root.position.copy(player.pos);
  player.character.root.rotation.y = player.facing;
  ui.updateParty(player);
  ui.setElement(player.data.element);
  quest.start();
  camState.yaw = 0;
  camState.pitch = 0.27;
  camState.targetDist = 7.4;
  game.mode = 'playing';
  ui.toast('Jelajahi pulau. Ikuti <b>penanda emas</b> untuk memulai.', '✦');
}

function togglePause() {
  if (game.mode === 'playing') {
    ui.openPause();
  } else if (game.mode === 'paused') {
    ui.closePause();
  }
}

function cycleQuality() {
  game.qualityIndex = (game.qualityIndex + 1) % 3;
  game.quality = ['low', 'medium', 'high'][game.qualityIndex];
  renderer.setPixelRatio(pixelRatio());
  const label = document.querySelector('#toggle-quality b');
  if (label) label.textContent = game.quality === 'low' ? 'Rendah' : game.quality === 'medium' ? 'Sedang' : 'Tinggi';
}

function toggleAudio() {
  audio.setEnabled(!audio.enabled);
  const label = document.querySelector('#toggle-audio b');
  if (label) label.textContent = audio.enabled ? 'Nyala' : 'Mati';
}

function requestJump() {
  input.jumpPressed = true;
  input.jumpHeld = true;
  touchJumpHeld = true;
}

function releaseJump() {
  touchJumpHeld = false;
  input.jumpHeld = false;
}

function bindControls() {
  document.getElementById('btn-start').addEventListener('click', startGame);
  document.getElementById('btn-pause').addEventListener('click', () => {
    if (game.mode === 'playing' || game.mode === 'paused') togglePause();
  });
  document.getElementById('pause-resume').addEventListener('click', () => ui.closePause());
  document.getElementById('toggle-quality').addEventListener('click', cycleQuality);
  document.getElementById('toggle-audio').addEventListener('click', toggleAudio);
  document.getElementById('pause-restart').addEventListener('click', () => location.reload());

  const stop = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };
  const attack = document.getElementById('btn-attack');
  const skill = document.getElementById('btn-skill');
  const burst = document.getElementById('btn-burst');
  const jump = document.getElementById('btn-jump');

  attack.addEventListener('pointerdown', (event) => {
    stop(event);
    if (game.mode === 'playing') input.attackPressed = true;
  });
  skill.addEventListener('pointerdown', (event) => {
    stop(event);
    if (game.mode === 'playing') input.skillPressed = true;
  });
  burst.addEventListener('pointerdown', (event) => {
    stop(event);
    if (game.mode === 'playing') input.burstPressed = true;
  });
  jump.addEventListener('pointerdown', (event) => {
    stop(event);
    if (game.mode === 'playing') requestJump();
  });
  jump.addEventListener('pointerup', (event) => {
    stop(event);
    releaseJump();
  });
  jump.addEventListener('pointercancel', releaseJump);
  jump.addEventListener('pointerleave', releaseJump);

  document.querySelectorAll('.char-chip').forEach((chip) => {
    chip.addEventListener('pointerdown', (event) => {
      stop(event);
      if (game.mode !== 'playing') return;
      player.switchTo(Number(chip.dataset.char));
      audio.sfx('ui');
    });
  });

  // Keyboard
  window.addEventListener('keydown', (event) => {
    if (event.code === 'Escape') {
      if (game.mode === 'playing' || game.mode === 'paused') {
        event.preventDefault();
        togglePause();
      }
      return;
    }
    if (game.mode !== 'playing') return;
    const code = event.code;
    if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(code)) event.preventDefault();
    keys.add(code);
    if (event.repeat) return;
    if (code === 'Space') {
      requestJump();
    } else if (code === 'KeyE') {
      input.skillPressed = true;
    } else if (code === 'KeyQ') {
      input.burstPressed = true;
    } else if (code === 'KeyF') {
      input.interactPressed = true;
    } else if (code === 'Digit1') {
      player.switchTo(0);
    } else if (code === 'Digit2') {
      player.switchTo(1);
    } else if (code === 'KeyM') {
      toggleAudio();
      ui.toast(audio.enabled ? 'Suara <b>nyala</b>' : 'Suara <b>mati</b>', '♪');
    } else if (code === 'KeyJ') {
      input.attackPressed = true;
    }
  });
  window.addEventListener('keyup', (event) => {
    keys.delete(event.code);
    if (event.code === 'Space') {
      touchJumpHeld = false;
      input.jumpHeld = false;
    }
  });
  window.addEventListener('blur', () => {
    keys.clear();
    releaseJump();
  });

  // Mouse / touch camera on the canvas.
  canvas.addEventListener('pointerdown', (event) => {
    if (game.mode !== 'playing') return;
    if (event.pointerType === 'mouse' && event.button !== 0 && event.button !== 2) return;
    drag = {
      id: event.pointerId,
      x: event.clientX,
      y: event.clientY,
      lastX: event.clientX,
      lastY: event.clientY,
      moved: 0,
      start: performance.now(),
      type: event.pointerType,
      button: event.button,
    };
    canvas.setPointerCapture?.(event.pointerId);
  });
  canvas.addEventListener('pointermove', (event) => {
    if (!drag || drag.id !== event.pointerId) return;
    const dx = event.clientX - drag.lastX;
    const dy = event.clientY - drag.lastY;
    drag.lastX = event.clientX;
    drag.lastY = event.clientY;
    drag.moved += Math.abs(dx) + Math.abs(dy);
    const sens = drag.type === 'touch' ? 0.0062 : 0.0046;
    camState.yaw -= dx * sens;
    camState.pitch = clamp(camState.pitch + dy * sens * 0.8, 0.02, 1.12);
  });
  const endDrag = (event) => {
    if (!drag || drag.id !== event.pointerId) return;
    const quick = performance.now() - drag.start < 320;
    if (drag.type === 'mouse' && drag.button === 0 && drag.moved < 7 && quick && game.mode === 'playing') {
      input.attackPressed = true;
    }
    drag = null;
  };
  canvas.addEventListener('pointerup', endDrag);
  canvas.addEventListener('pointercancel', endDrag);
  canvas.addEventListener('contextmenu', (event) => event.preventDefault());
  canvas.addEventListener(
    'wheel',
    (event) => {
      event.preventDefault();
      camState.targetDist = clamp(camState.targetDist + event.deltaY * 0.0055, 3.6, 12);
    },
    { passive: false }
  );

  // Virtual joystick.
  const joyEl = document.getElementById('joystick');
  const stick = document.getElementById('stick');
  const moveJoy = (event) => {
    const rect = joyEl.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const maxR = rect.width * 0.32;
    let dx = event.clientX - cx;
    let dy = event.clientY - cy;
    const len = Math.hypot(dx, dy);
    if (len > maxR) {
      dx = (dx / len) * maxR;
      dy = (dy / len) * maxR;
    }
    joy.x = dx / maxR;
    joy.y = -dy / maxR;
    stick.style.transform = `translate(${dx * 0.82}px, ${dy * 0.82}px)`;
  };
  joyEl.addEventListener('pointerdown', (event) => {
    event.preventDefault();
    event.stopPropagation();
    joy.active = true;
    joy.pointerId = event.pointerId;
    joyEl.setPointerCapture(event.pointerId);
    moveJoy(event);
  });
  joyEl.addEventListener('pointermove', (event) => {
    if (!joy.active || joy.pointerId !== event.pointerId) return;
    event.preventDefault();
    moveJoy(event);
  });
  const endJoy = (event) => {
    if (joy.pointerId !== event.pointerId) return;
    joy.active = false;
    joy.pointerId = null;
    joy.x = 0;
    joy.y = 0;
    stick.style.transform = 'translate(0px, 0px)';
  };
  joyEl.addEventListener('pointerup', endJoy);
  joyEl.addEventListener('pointercancel', endJoy);

  // Pause menu label sync on load.
  const qLabel = document.querySelector('#toggle-quality b');
  if (qLabel) qLabel.textContent = quality === 'low' ? 'Rendah' : quality === 'medium' ? 'Sedang' : 'Tinggi';

  window.addEventListener('resize', onResize);
  window.addEventListener('orientationchange', () => setTimeout(onResize, 220));
}

function onResize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(pixelRatio());
  renderer.setSize(w, h);
  composer?.setSize(w, h);
  bloom?.setSize(w, h);
}

function updateCamera(dt, snap = false) {
  camState.dist = damp(camState.dist, camState.targetDist, 8, dt);
  const target = new THREE.Vector3(player.pos.x, player.pos.y + 1.62, player.pos.z);
  const cosPitch = Math.cos(camState.pitch);
  const desired = new THREE.Vector3(
    target.x + Math.sin(camState.yaw) * cosPitch * camState.dist,
    target.y + Math.sin(camState.pitch) * camState.dist,
    target.z + Math.cos(camState.yaw) * cosPitch * camState.dist
  );

  // Never let the camera sink into a hill.
  const ground = heightAt(desired.x, desired.z);
  const minY = Math.max(ground, WATER_Y) + 0.55;
  if (desired.y < minY) desired.y = minY;

  if (snap) camera.position.copy(desired);
  else camera.position.lerp(desired, 1 - Math.exp(-13 * dt));

  if (player.shake > 0.002) {
    const s = player.shake * 0.34;
    camera.position.x += (Math.random() - 0.5) * s;
    camera.position.y += (Math.random() - 0.5) * s;
    camera.position.z += (Math.random() - 0.5) * s;
  }

  camera.lookAt(target);
  camera.userData.yaw = camState.yaw;
}

function gatherInput() {
  const keyboardX = (keys.has('KeyD') ? 1 : 0) - (keys.has('KeyA') ? 1 : 0);
  const keyboardY = (keys.has('KeyW') ? 1 : 0) - (keys.has('KeyS') ? 1 : 0);
  let x = keyboardX + joy.x;
  let y = keyboardY + joy.y;
  const len = Math.hypot(x, y);
  if (len > 1) {
    x /= len;
    y /= len;
  }
  input.x = x;
  input.y = y;
  const joyMag = Math.hypot(joy.x, joy.y);
  input.sprint = keys.has('ShiftLeft') || keys.has('ShiftRight') || joyMag > 0.92;
  input.jumpHeld = keys.has('Space') || touchJumpHeld;
}

function clearPressed() {
  input.jumpPressed = false;
  input.attackPressed = false;
  input.skillPressed = false;
  input.burstPressed = false;
  input.interactPressed = false;
}

function updatePlaying(dt) {
  gatherInput();
  camera.userData.yaw = camState.yaw;
  player.update(dt, input, camState.yaw, game.elapsed);
  enemies.update(dt, player, game.elapsed);
  quest.update(player.pos);
  updateCamera(dt);

  // Interaction prompt & quest markers.
  currentInteraction = quest.nearestInteraction(player.pos);
  ui.setInteraction(currentInteraction);
  if (input.interactPressed && currentInteraction) {
    quest.interact(player.pos);
  }

  const marker = quest.getMarker();
  ui.updateMarker(marker, camera);
  ui.updateBoss(enemies.bossBarData, camera, player.pos);
  ui.updateHud(player.stats(), player);

  minimapTimer -= dt;
  if (minimapTimer <= 0) {
    minimapTimer = 0.08;
    ui.drawMinimap(player, quest, enemies, camState.yaw);
  }

  clearPressed();
}

function updateNonPlaying(dt) {
  if (player) {
    player.character.anim.attack = -1;
    player.character.update(dt, { speed: 0, onGround: true, elapsed: game.elapsed });
    player.character.root.position.copy(player.pos);
    player.character.root.rotation.y = player.facing;
  }
  ui.setInteraction(null);
  clearPressed();
}

function loop(now) {
  requestAnimationFrame(loop);
  const dt = Math.min(0.05, Math.max(0.0001, (now - clock.last) / 1000));
  clock.last = now;
  game.elapsed += dt;

  if (game.mode === 'title') {
    camState.yaw += dt * 0.07;
    updateNonPlaying(dt);
    updateCamera(dt);
    world.update(dt, game.elapsed, player.pos);
    ui.updateMarker(null, camera);
  } else if (game.mode === 'playing') {
    updatePlaying(dt);
    world.update(dt, game.elapsed, player.pos);
  } else {
    updateNonPlaying(dt);
    if (game.mode !== 'paused' && game.mode !== 'dead') {
      // Keep ambient time alive for dialogue and reward screens.
      world.update(dt, game.elapsed, player.pos);
      updateCamera(dt);
    }
    if (game.mode === 'dialogue' || game.mode === 'reward') {
      world.update(dt, game.elapsed, player.pos);
